const EXS=[{"id":"hdr","title":"Start here: blink + button + UART (stm32f1.h)","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\n\nstatic void uart_putc(char c) { while (!(USART1->SR & 0x80)); USART1->DR = c; }\nstatic void uart_puts(const char *s) { while (*s) uart_putc(*s++); }\n\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_IOPCEN | RCC_APB2ENR_USART1EN;\n    gpio_cfg(GPIOC, 13, GPIO_OUT_PP_2MHZ);          /* onboard LED          */\n    gpio_cfg(GPIOA, 5,  GPIO_OUT_PP_2MHZ);          /* external LED         */\n    gpio_cfg(GPIOA, 0,  GPIO_IN_PULL);              /* button, pulled up    */\n    GPIOA->ODR |= 1u;\n    gpio_cfg(GPIOA, 9,  GPIO_AF_PP_2MHZ);           /* USART1 TX            */\n    USART1->BRR = 69;                               /* 8 MHz / 115200       */\n    USART1->CR1 = (1u << 13) | (1u << 3);           /* UE | TE              */\n    SysTick->LOAD = 8000 - 1;                       /* 1 ms tick            */\n    SysTick->CTRL = 7;\n\n    uart_puts(\"Hello from main.c!\\r\\n\");\n    uint32_t last = 0;\n    while (1) {\n        if (ms - last >= 500) { last = ms; GPIOC->ODR ^= 1u << 13; }\n        if (GPIOA->IDR & 1u) GPIOA->BSRR = 1u << 21;    /* released: LED off */\n        else                 GPIOA->BSRR = 1u << 5;     /* pressed:  LED on  */\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"btn1","type":"btn","x":360,"y":100,"attrs":{"color":"green"}},{"id":"led1","type":"led","x":360,"y":240,"attrs":{"color":"red"}}],"wires":[["led1:A","bluepill:PA5","green"],["led1:C","bluepill:GND.3","black"],["btn1:1.l","bluepill:PA0","blue"],["btn1:2.l","bluepill:GND.2","black"]]}},{"id":"irq","title":"Interrupts: EXTI button + TIM2 timer + UART","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n\nstatic volatile uint32_t presses;\n\nvoid EXTI0_IRQHandler(void) {          /* button on PA0, falling edge */\n    EXTI->PR = 1;                      /* clear the pending flag first */\n    presses++;\n}\n\nvoid TIM2_IRQHandler(void) {           /* timer tick, twice a second */\n    TIM2->SR &= ~1u;\n    GPIOC->ODR ^= 1u << 13;            /* blink the onboard LED */\n}\n\nstatic void uart_putc(char c) { while (!(USART1->SR & 0x80)); USART1->DR = c; }\nstatic void uart_puts(const char *s) { while (*s) uart_putc(*s++); }\nstatic void uart_num(uint32_t v) {\n    char b[11]; int i = 0;\n    do { b[i++] = '0' + v % 10; v /= 10; } while (v);\n    while (i) uart_putc(b[--i]);\n}\n\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_IOPCEN | RCC_APB2ENR_AFIOEN | RCC_APB2ENR_USART1EN;\n    RCC->APB1ENR |= RCC_APB1ENR_TIM2EN;\n    gpio_cfg(GPIOC, 13, GPIO_OUT_PP_2MHZ);\n    gpio_cfg(GPIOA, 5,  GPIO_OUT_PP_2MHZ);\n    gpio_cfg(GPIOA, 0,  GPIO_IN_PULL);  GPIOA->ODR |= 1u;     /* button, pulled up */\n    gpio_cfg(GPIOA, 9,  GPIO_AF_PP_2MHZ);\n    USART1->BRR = 69;  USART1->CR1 = (1u << 13) | (1u << 3);\n\n    AFIO->EXTICR[0] = 0;               /* EXTI0 listens to PA0 */\n    EXTI->FTSR |= 1u;                  /* falling edge */\n    EXTI->IMR  |= 1u;                  /* unmask line 0 */\n    NVIC_SetPriority(EXTI0_IRQn, 1);   /* button is more urgent than the timer */\n    NVIC_EnableIRQ(EXTI0_IRQn);\n\n    TIM2->PSC = 7999;  TIM2->ARR = 499;   /* 8 MHz / 8000 / 500 = 2 Hz */\n    TIM2->DIER = 1;  TIM2->CR1 = 1;\n    NVIC_SetPriority(TIM2_IRQn, 5);\n    NVIC_EnableIRQ(TIM2_IRQn);\n\n    uart_puts(\"Interrupts demo: press the button\\r\\n\");\n    uint32_t shown = 0;\n    for (;;) {\n        if (presses != shown) {\n            shown = presses;\n            GPIOA->ODR ^= 1u << 5;     /* toggle the LED on PA5 */\n            uart_puts(\"presses = \"); uart_num(shown); uart_puts(\"\\r\\n\");\n        }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"btn1","type":"btn","x":360,"y":100,"attrs":{"color":"green"}},{"id":"led1","type":"led","x":360,"y":240,"attrs":{"color":"red"}}],"wires":[["led1:A","bluepill:PA5","green"],["led1:C","bluepill:GND.3","black"],["btn1:1.l","bluepill:PA0","blue"],["btn1:2.l","bluepill:GND.2","black"]]}},{"id":"blank","title":"Blank project (edit me)","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPCEN;\n    gpio_cfg(GPIOC, 13, GPIO_OUT_PP_2MHZ);\n    while (1) {\n        GPIOC->ODR ^= 1u << 13;                     /* toggle the onboard LED */\n        for (volatile int i = 0; i < 300000; i++);  /* crude delay            */\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"btn1","type":"btn","x":360,"y":100,"attrs":{"color":"green"}},{"id":"led1","type":"led","x":360,"y":240,"attrs":{"color":"red"}}],"wires":[["led1:A","bluepill:PA5","green"],["led1:C","bluepill:GND.3","black"],["btn1:1.l","bluepill:PA0","blue"],["btn1:2.l","bluepill:GND.2","black"]]}},{"id":"lcd_clock","title":"LCD 16x2: hello + uptime (HD44780)","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n/* LCD1602 (4-bit): RS=PA0  E=PA1  D4..D7=PA2..PA5  — shows a title and an uptime counter. */\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\nstatic void delay_us(uint32_t us) { for (volatile uint32_t i = 0; i < us; i++); }\nstatic void pulse(void) { GPIOA->BSRR = 2u; delay_us(2); GPIOA->BSRR = 2u << 16; delay_us(2); }\nstatic void put4(uint8_t v) { GPIOA->ODR = (GPIOA->ODR & ~(0xFu << 2)) | ((uint32_t)(v & 15) << 2); pulse(); }\nstatic void send(uint8_t v, int rs) { if (rs) GPIOA->BSRR = 1u; else GPIOA->BSRR = 1u << 16; put4(v >> 4); put4(v & 15); delay_us(8); }\nstatic void cmd(uint8_t c) { send(c, 0); }\nstatic void put(char c) { send((uint8_t)c, 1); }\nstatic void text(const char *s) { while (*s) put(*s++); }\nstatic void goto_xy(int col, int row) { cmd(0x80 | ((row ? 0x40 : 0) + col)); }\nstatic void lcd_init(void) {\n    delay_us(2000); GPIOA->BSRR = 1u << 16;\n    put4(3); delay_us(200); put4(3); delay_us(50); put4(3); delay_us(50); put4(2);   /* enter 4-bit mode */\n    cmd(0x28); cmd(0x0C); cmd(0x06); cmd(0x01); delay_us(300);\n}\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN;\n    for (int i = 0; i < 6; i++) gpio_cfg(GPIOA, i, GPIO_OUT_PP_2MHZ);\n    SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7;                       /* 1 ms tick */\n    lcd_init();\n    static const uint8_t heart[8] = {0, 10, 31, 31, 14, 4, 0, 0};\n    cmd(0x40); for (int i = 0; i < 8; i++) put((char)heart[i]);           /* custom character 0 */\n    goto_xy(0, 0); text(\"Hello, PinForge!\");\n    uint32_t shown = 99999;\n    for (;;) {\n        uint32_t s = ms / 1000;\n        if (s != shown) {\n            shown = s; goto_xy(0, 1); text(\"Uptime: \");\n            char b[6]; int n = 0; uint32_t v = s; do { b[n++] = (char)('0' + v % 10); v /= 10; } while (v);\n            while (n) put(b[--n]);\n            text(\" s  \"); put(0);\n        }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"lcd1","type":"lcd","x":260,"y":320,"attrs":{}}],"wires":[["lcd1:VSS","bluepill:GND.2","black"],["lcd1:V0","bluepill:GND.3","black"],["lcd1:RW","bluepill:GND.2","black"],["lcd1:RS","bluepill:PA0","green"],["lcd1:E","bluepill:PA1","yellow"],["lcd1:D4","bluepill:PA2","blue"],["lcd1:D5","bluepill:PA3","blue"],["lcd1:D6","bluepill:PA4","blue"],["lcd1:D7","bluepill:PA5","blue"],["lcd1:VDD","bluepill:5V","red"],["lcd1:A","bluepill:5V","red"],["lcd1:K","bluepill:GND.3","black"]]}},{"id":"keypad_lcd","title":"Keypad 4x4 + LCD: type on the display","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n/* 4x4 keypad + LCD1602. Keys you press are shown on line 2; * = backspace, # = clear.\n   LCD: RS=PA0 E=PA1 D4..D7=PA2..PA5   Keypad: columns C1..C4 = PA6,PA7,PB0,PB1 (outputs), rows R1..R4 = PB12..PB15 (pull-up inputs) */\nstatic void us(uint32_t n) { for (volatile uint32_t i = 0; i < n; i++); }\nstatic void pulse(void) { GPIOA->BSRR = 2u; us(2); GPIOA->BSRR = 2u << 16; us(2); }\nstatic void put4(uint8_t v) { GPIOA->ODR = (GPIOA->ODR & ~(0xFu << 2)) | ((uint32_t)(v & 15) << 2); pulse(); }\nstatic void send(uint8_t v, int rs) { if (rs) GPIOA->BSRR = 1u; else GPIOA->BSRR = 1u << 16; put4(v >> 4); put4(v & 15); us(8); }\nstatic void cmd(uint8_t c) { send(c, 0); }\nstatic void put(char c) { send((uint8_t)c, 1); }\nstatic void text(const char *s) { while (*s) put(*s++); }\nstatic void at(int col, int row) { cmd(0x80 | ((row ? 0x40 : 0) + col)); }\nstatic void col_low(int c) {                                   /* drive one column low, the others high */\n    GPIOA->ODR |= 3u << 6; GPIOB->ODR |= 3u;\n    if (c < 2) GPIOA->ODR &= ~(1u << (6 + c)); else GPIOB->ODR &= ~(1u << (c - 2));\n}\nstatic int scan(void) {\n    static const char K[16] = {'1','2','3','A','4','5','6','B','7','8','9','C','*','0','#','D'};\n    int found = -1;\n    for (int c = 0; c < 4 && found < 0; c++) {\n        col_low(c); us(10); uint32_t r = (GPIOB->IDR >> 12) & 15u;\n        for (int rr = 0; rr < 4; rr++) if (!(r & (1u << rr))) { found = K[rr * 4 + c]; break; }\n    }\n    GPIOA->ODR |= 3u << 6; GPIOB->ODR |= 3u; return found;\n}\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_IOPBEN;\n    for (int i = 0; i < 8; i++) gpio_cfg(GPIOA, i, GPIO_OUT_PP_2MHZ);\n    gpio_cfg(GPIOB, 0, GPIO_OUT_PP_2MHZ); gpio_cfg(GPIOB, 1, GPIO_OUT_PP_2MHZ);\n    for (int i = 12; i < 16; i++) gpio_cfg(GPIOB, i, GPIO_IN_PULL);\n    GPIOB->ODR |= 0xF003u;\n    us(2000); GPIOA->BSRR = 1u << 16; put4(3); us(200); put4(3); us(50); put4(3); us(50); put4(2);\n    cmd(0x28); cmd(0x0C); cmd(0x06); cmd(0x01); us(300);\n    at(0, 0); text(\"Keypad + LCD\"); at(0, 1); text(\"> \");\n    char buf[15]; int len = 0, last = -1;\n    for (;;) {\n        int k = scan();\n        if (k != last && k > 0) {\n            if (k == '#') len = 0; else if (k == '*') { if (len) len--; } else if (len < 14) buf[len++] = (char)k;\n            at(2, 1); for (int i = 0; i < 14; i++) put(i < len ? buf[i] : ' ');\n        }\n        last = k; us(300);\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"lcd1","type":"lcd","x":250,"y":200,"attrs":{}},{"id":"kp1","type":"kp","x":480,"y":500,"attrs":{}}],"wires":[["lcd1:VSS","bluepill:GND.2","black"],["lcd1:V0","bluepill:GND.3","black"],["lcd1:RW","bluepill:GND.2","black"],["lcd1:RS","bluepill:PA0","green"],["lcd1:E","bluepill:PA1","yellow"],["lcd1:D4","bluepill:PA2","blue"],["lcd1:D5","bluepill:PA3","blue"],["lcd1:D6","bluepill:PA4","blue"],["lcd1:D7","bluepill:PA5","blue"],["lcd1:VDD","bluepill:5V","red"],["lcd1:A","bluepill:5V","red"],["lcd1:K","bluepill:GND.3","black"],["kp1:R1","bluepill:PB12","blue"],["kp1:R2","bluepill:PB13","blue"],["kp1:R3","bluepill:PB14","blue"],["kp1:R4","bluepill:PB15","blue"],["kp1:C1","bluepill:PA6","green"],["kp1:C2","bluepill:PA7","green"],["kp1:C3","bluepill:PB0","green"],["kp1:C4","bluepill:PB1","green"]]}},{"id":"seg7_count","title":"7-segment digit: counter with decimal point","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n/* One 7-segment digit (common cathode): A..G = PA0..PA6, DP = PA7. Counts 0-9 twice a second. */\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\nstatic const uint8_t digit[10] = {0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F};   /* bit0 = A ... bit6 = G */\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN;\n    for (int i = 0; i < 8; i++) gpio_cfg(GPIOA, i, GPIO_OUT_PP_2MHZ);\n    SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7;\n    uint32_t n = 0, last = 0;\n    for (;;) {\n        if (ms - last >= 500) { last = ms; n = (n + 1) % 10; }\n        GPIOA->ODR = (GPIOA->ODR & ~0xFFu) | digit[n] | ((n & 1) ? 0x80u : 0);      /* DP lights on odd digits */\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"seg1","type":"seg7","x":400,"y":120,"attrs":{"common":"cathode","color":"red"}}],"wires":[["seg1:A","bluepill:PA0","green"],["seg1:B","bluepill:PA1","green"],["seg1:C","bluepill:PA2","green"],["seg1:D","bluepill:PA3","green"],["seg1:E","bluepill:PA4","green"],["seg1:F","bluepill:PA5","green"],["seg1:G","bluepill:PA6","green"],["seg1:DP","bluepill:PA7","green"],["seg1:COM.1","bluepill:GND.2","black"]]}},{"id":"seg4_count","title":"4-digit 7-segment: multiplexed counter","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n/* 4-digit multiplexed display (common cathode). Segments A..G,DP = PA0..PA7, digit selects DIG1..DIG4 = PB12..PB15.\n   A SysTick interrupt shows one digit per millisecond (250 Hz refresh); main() counts up. */\nstatic const uint8_t T[10] = {0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F};\nstatic volatile uint32_t number, scan;\nvoid SysTick_Handler(void) {\n    static const uint32_t place[4] = {1000, 100, 10, 1};\n    GPIOB->ODR |= 0xF000u;                                    /* blank all digits first */\n    GPIOA->ODR = (GPIOA->ODR & ~0xFFu) | T[(number / place[scan]) % 10];\n    GPIOB->ODR &= ~(1u << (12 + scan));                       /* then enable one */\n    scan = (scan + 1) & 3;\n}\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_IOPBEN;\n    for (int i = 0; i < 8; i++) gpio_cfg(GPIOA, i, GPIO_OUT_PP_2MHZ);\n    for (int i = 12; i < 16; i++) gpio_cfg(GPIOB, i, GPIO_OUT_PP_2MHZ);\n    SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7;\n    for (;;) { for (volatile uint32_t i = 0; i < 80000; i++); number = (number + 1) % 10000; }\n}\n","b64":"","circuit":{"parts":[{"id":"seg1","type":"seg4","x":300,"y":280,"attrs":{"common":"cathode","color":"red"}}],"wires":[["seg1:A","bluepill:PA0","green"],["seg1:B","bluepill:PA1","green"],["seg1:C","bluepill:PA2","green"],["seg1:D","bluepill:PA3","green"],["seg1:E","bluepill:PA4","green"],["seg1:F","bluepill:PA5","green"],["seg1:G","bluepill:PA6","green"],["seg1:DP","bluepill:PA7","green"],["seg1:DIG1","bluepill:PB12","yellow"],["seg1:DIG2","bluepill:PB13","yellow"],["seg1:DIG3","bluepill:PB14","yellow"],["seg1:DIG4","bluepill:PB15","yellow"]]}},{"id":"buzzer_melody","title":"Buzzer: C-major scale (PWM tones)","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n/* Plays a C-major scale on a buzzer. TIM3 channel 1 (PA6) makes a square wave at the note frequency. */\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\nstatic void wait(uint32_t t) { uint32_t s = ms; while (ms - s < t); }\nstatic void tone(uint32_t hz) {\n    if (!hz) { TIM3->CCER = 0; return; }\n    TIM3->ARR = 1000000 / hz - 1; TIM3->CCR1 = (1000000 / hz) / 2; TIM3->CCER = 1; TIM3->EGR = 1;\n}\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_AFIOEN; RCC->APB1ENR |= RCC_APB1ENR_TIM3EN;\n    gpio_cfg(GPIOA, 6, GPIO_AF_PP_2MHZ);\n    TIM3->PSC = 7;                                             /* 8 MHz / 8 = 1 MHz timer clock */\n    TIM3->CCMR1 = (6u << 4) | (1u << 3); TIM3->CR1 = 1;       /* PWM mode 1 on channel 1 */\n    SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7;\n    static const uint16_t notes[8] = {262, 294, 330, 349, 392, 440, 494, 523};\n    for (;;) for (int i = 0; i < 8; i++) { tone(notes[i]); wait(300); tone(0); wait(60); }\n}\n","b64":"","circuit":{"parts":[{"id":"buz1","type":"buzz","x":400,"y":200,"attrs":{}}],"wires":[["buz1:1","bluepill:PA6","orange"],["buz1:2","bluepill:GND.2","black"]]}},{"id":"rgb_fade","title":"RGB LED: colour wheel (PWM mixing)","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n/* RGB LED (common cathode): R=PA6, G=PA7, B=PB0 on TIM3 PWM channels 1..3. Walks around the colour wheel. */\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\nstatic uint32_t level(uint32_t h) {                            /* 0..1000 triangle wave over a 6 x 100 hue cycle */\n    h %= 600; if (h < 100) return h * 10; if (h < 300) return 1000; if (h < 400) return (400 - h) * 10; return 0;\n}\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_IOPBEN | RCC_APB2ENR_AFIOEN; RCC->APB1ENR |= RCC_APB1ENR_TIM3EN;\n    gpio_cfg(GPIOA, 6, GPIO_AF_PP_2MHZ); gpio_cfg(GPIOA, 7, GPIO_AF_PP_2MHZ); gpio_cfg(GPIOB, 0, GPIO_AF_PP_2MHZ);\n    TIM3->PSC = 7; TIM3->ARR = 999;                            /* 1 kHz PWM */\n    TIM3->CCMR1 = (6u << 4) | (1u << 3) | (6u << 12) | (1u << 11); TIM3->CCMR2 = (6u << 4) | (1u << 3);\n    TIM3->CCER = 1u | (1u << 4) | (1u << 8); TIM3->CR1 = 1;\n    SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7;\n    uint32_t last = 0, h = 0;\n    for (;;) {\n        if (ms - last >= 10) { last = ms; h = (h + 3) % 600;\n            TIM3->CCR1 = level(h + 200); TIM3->CCR2 = level(h); TIM3->CCR3 = level(h + 400); }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"rgb1","type":"rgb","x":400,"y":200,"attrs":{"common":"cathode"}}],"wires":[["rgb1:R","bluepill:PA6","red"],["rgb1:G","bluepill:PA7","green"],["rgb1:B","bluepill:PB0","blue"],["rgb1:COM","bluepill:GND.2","black"]]}},{"id":"servo_sweep","title":"Servo: sweep 0 to 180 degrees","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n/* Servo on TIM3 channel 1 (PA6): 50 Hz, pulse 1.0 ms = 0 deg ... 2.0 ms = 180 deg. Sweeps back and forth. */\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_AFIOEN; RCC->APB1ENR |= RCC_APB1ENR_TIM3EN; gpio_cfg(GPIOA, 6, GPIO_AF_PP_2MHZ);\n    TIM3->PSC = 7; TIM3->ARR = 19999; TIM3->CCR1 = 1500;       /* 1 MHz clock, 20 ms period */\n    TIM3->CCMR1 = (6u << 4) | (1u << 3); TIM3->CCER = 1; TIM3->CR1 = 1;\n    SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7;\n    int pulse = 1000, step = 10; uint32_t last = 0;\n    for (;;) {\n        if (ms - last >= 20) { last = ms; pulse += step; if (pulse >= 2000 || pulse <= 1000) step = -step; TIM3->CCR1 = (uint32_t)pulse; }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"srv1","type":"servo","x":400,"y":240,"attrs":{"min":"1000","max":"2000"}}],"wires":[["srv1:PWM","bluepill:PA6","orange"],["srv1:GND","bluepill:GND.2","black"],["srv1:V+","bluepill:5V","red"]]}},{"id":"oled_hello","title":"OLED 128x64 (SSD1306, I2C2): hello + uptime","src":"/* SSD1306 OLED 128x64 on I2C2: SCL = PB10, SDA = PB11, address 0x3C.\n   Register-level driver (no library): text in a 5x7 font plus an uptime counter.\n   I2C1 (PB6 / PB7) works the same way: use I2C1 instead of I2C2 and pins 6 / 7. */\n#include <stdint.h>\n#include \"stm32f1.h\"\n\nstatic const uint8_t font5x7[95][5] = {   /* ASCII 32..126, one byte per column, bit 0 = top row */\n    {0x00,0x00,0x00,0x00,0x00}, {0x00,0x00,0x5f,0x00,0x00}, {0x00,0x07,0x00,0x07,0x00}, {0x14,0x7f,0x14,0x7f,0x14},\n    {0x24,0x2a,0x7f,0x2a,0x12}, {0x23,0x13,0x08,0x64,0x62}, {0x36,0x49,0x56,0x20,0x50}, {0x00,0x08,0x07,0x03,0x00},\n    {0x00,0x1c,0x22,0x41,0x00}, {0x00,0x41,0x22,0x1c,0x00}, {0x2a,0x1c,0x7f,0x1c,0x2a}, {0x08,0x08,0x3e,0x08,0x08},\n    {0x00,0x80,0x70,0x30,0x00}, {0x08,0x08,0x08,0x08,0x08}, {0x00,0x00,0x60,0x60,0x00}, {0x20,0x10,0x08,0x04,0x02},\n    {0x3e,0x51,0x49,0x45,0x3e}, {0x00,0x42,0x7f,0x40,0x00}, {0x72,0x49,0x49,0x49,0x46}, {0x21,0x41,0x49,0x4d,0x33},\n    {0x18,0x14,0x12,0x7f,0x10}, {0x27,0x45,0x45,0x45,0x39}, {0x3c,0x4a,0x49,0x49,0x31}, {0x41,0x21,0x11,0x09,0x07},\n    {0x36,0x49,0x49,0x49,0x36}, {0x46,0x49,0x49,0x29,0x1e}, {0x00,0x00,0x14,0x00,0x00}, {0x00,0x40,0x34,0x00,0x00},\n    {0x00,0x08,0x14,0x22,0x41}, {0x14,0x14,0x14,0x14,0x14}, {0x00,0x41,0x22,0x14,0x08}, {0x02,0x01,0x59,0x09,0x06},\n    {0x3e,0x41,0x5d,0x59,0x4e}, {0x7c,0x12,0x11,0x12,0x7c}, {0x7f,0x49,0x49,0x49,0x36}, {0x3e,0x41,0x41,0x41,0x22},\n    {0x7f,0x41,0x41,0x41,0x3e}, {0x7f,0x49,0x49,0x49,0x41}, {0x7f,0x09,0x09,0x09,0x01}, {0x3e,0x41,0x41,0x51,0x73},\n    {0x7f,0x08,0x08,0x08,0x7f}, {0x00,0x41,0x7f,0x41,0x00}, {0x20,0x40,0x41,0x3f,0x01}, {0x7f,0x08,0x14,0x22,0x41},\n    {0x7f,0x40,0x40,0x40,0x40}, {0x7f,0x02,0x1c,0x02,0x7f}, {0x7f,0x04,0x08,0x10,0x7f}, {0x3e,0x41,0x41,0x41,0x3e},\n    {0x7f,0x09,0x09,0x09,0x06}, {0x3e,0x41,0x51,0x21,0x5e}, {0x7f,0x09,0x19,0x29,0x46}, {0x26,0x49,0x49,0x49,0x32},\n    {0x03,0x01,0x7f,0x01,0x03}, {0x3f,0x40,0x40,0x40,0x3f}, {0x1f,0x20,0x40,0x20,0x1f}, {0x3f,0x40,0x38,0x40,0x3f},\n    {0x63,0x14,0x08,0x14,0x63}, {0x03,0x04,0x78,0x04,0x03}, {0x61,0x59,0x49,0x4d,0x43}, {0x00,0x7f,0x41,0x41,0x41},\n    {0x02,0x04,0x08,0x10,0x20}, {0x00,0x41,0x41,0x7f,0x00}, {0x04,0x02,0x01,0x02,0x04}, {0x40,0x40,0x40,0x40,0x40},\n    {0x00,0x03,0x07,0x08,0x00}, {0x20,0x54,0x54,0x78,0x40}, {0x7f,0x28,0x44,0x44,0x38}, {0x38,0x44,0x44,0x44,0x28},\n    {0x38,0x44,0x44,0x28,0x7f}, {0x38,0x54,0x54,0x54,0x18}, {0x00,0x08,0x7e,0x09,0x02}, {0x18,0xa4,0xa4,0x9c,0x78},\n    {0x7f,0x08,0x04,0x04,0x78}, {0x00,0x44,0x7d,0x40,0x00}, {0x20,0x40,0x40,0x3d,0x00}, {0x7f,0x10,0x28,0x44,0x00},\n    {0x00,0x41,0x7f,0x40,0x00}, {0x7c,0x04,0x78,0x04,0x78}, {0x7c,0x08,0x04,0x04,0x78}, {0x38,0x44,0x44,0x44,0x38},\n    {0xfc,0x18,0x24,0x24,0x18}, {0x18,0x24,0x24,0x18,0xfc}, {0x7c,0x08,0x04,0x04,0x08}, {0x48,0x54,0x54,0x54,0x24},\n    {0x04,0x04,0x3f,0x44,0x24}, {0x3c,0x40,0x40,0x20,0x7c}, {0x1c,0x20,0x40,0x20,0x1c}, {0x3c,0x40,0x30,0x40,0x3c},\n    {0x44,0x28,0x10,0x28,0x44}, {0x4c,0x90,0x90,0x90,0x7c}, {0x44,0x64,0x54,0x4c,0x44}, {0x00,0x08,0x36,0x41,0x00},\n    {0x00,0x00,0x77,0x00,0x00}, {0x00,0x41,0x36,0x08,0x00}, {0x02,0x01,0x02,0x04,0x02},\n};\n#define OLED_ADDR 0x3C\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\n\nstatic void i2c_init(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPBEN | RCC_APB2ENR_AFIOEN;\n    RCC->APB1ENR |= RCC_APB1ENR_I2C2EN;\n    gpio_cfg(GPIOB, 10, GPIO_AF_OD_50MHZ);         /* SCL */\n    gpio_cfg(GPIOB, 11, GPIO_AF_OD_50MHZ);          /* SDA */\n    I2C2->CR2 = 8;                                 /* PCLK1 = 8 MHz */\n    I2C2->CCR = 40;                                /* 8 MHz / (2 x 40) = 100 kHz */\n    I2C2->TRISE = 9;\n    I2C2->CR1 = I2C_CR1_PE;\n}\nstatic int i2c_start(uint8_t addr_rw) {              /* returns 1 on ACK, 0 on NACK */\n    I2C2->CR1 |= I2C_CR1_START;\n    while (!(I2C2->SR1 & I2C_SR1_SB));\n    I2C2->DR = addr_rw;\n    for (;;) {\n        uint32_t s = I2C2->SR1;\n        if (s & I2C_SR1_ADDR) { (void)I2C2->SR2; return 1; }\n        if (s & I2C_SR1_AF) { I2C2->SR1 &= ~I2C_SR1_AF; I2C2->CR1 |= I2C_CR1_STOP; while (I2C2->CR1 & I2C_CR1_STOP); return 0; }\n    }\n}\nstatic void i2c_put(uint8_t b) { while (!(I2C2->SR1 & I2C_SR1_TXE)); I2C2->DR = b; }\nstatic void i2c_stop(void) { while (!(I2C2->SR1 & I2C_SR1_BTF)); I2C2->CR1 |= I2C_CR1_STOP; while (I2C2->CR1 & I2C_CR1_STOP); }\n\nstatic void oled_cmds(const uint8_t *c, int n) {\n    if (!i2c_start(OLED_ADDR << 1)) return;\n    i2c_put(0x00);                                 /* control byte: command stream */\n    while (n--) i2c_put(*c++);\n    i2c_stop();\n}\nstatic void oled_data(const uint8_t *d, int n) {\n    if (!i2c_start(OLED_ADDR << 1)) return;\n    i2c_put(0x40);                                 /* control byte: data stream */\n    while (n--) i2c_put(*d++);\n    i2c_stop();\n}\nstatic void oled_init(void) {\n    static const uint8_t init[] = {\n        0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40, 0x8D, 0x14,   /* off, clock, mux 64, offset, start line, charge pump on */\n        0x20, 0x02, 0xA1, 0xC8, 0xDA, 0x12, 0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6, 0xAF };\n    oled_cmds(init, sizeof init);\n}\nstatic void oled_pos(int page, int col) {\n    uint8_t c[3] = { (uint8_t)(0xB0 | page), (uint8_t)(col & 15), (uint8_t)(0x10 | (col >> 4)) };\n    oled_cmds(c, 3);\n}\nstatic void oled_clear(void) {\n    static const uint8_t zero[128];\n    for (int p = 0; p < 8; p++) { oled_pos(p, 0); oled_data(zero, 128); }\n}\nstatic void oled_text(int page, int col, const char *s) {\n    uint8_t buf[128]; int n = 0;\n    for (; *s && n + 6 <= 128; s++) {\n        const uint8_t *g = font5x7[(*s - 32) % 95];\n        for (int i = 0; i < 5; i++) buf[n++] = g[i];\n        buf[n++] = 0;\n    }\n    oled_pos(page, col); oled_data(buf, n);\n}\nstatic void oled_rule(int page) { uint8_t b[128]; for (int i = 0; i < 128; i++) b[i] = 0x08; oled_pos(page, 0); oled_data(b, 128); }\n\nint main(void) {\n    i2c_init();\n    SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7;   /* 1 ms tick */\n    oled_init();\n    oled_clear();\n    oled_text(0, 0, \"Hello, PinForge!\");\n    oled_rule(1);\n    oled_text(2, 0, \"SSD1306 128x64\");\n    oled_text(4, 0, \"I2C2 100 kHz  0x3C\");\n    uint32_t shown = 99999;\n    for (;;) {\n        uint32_t s = ms / 1000;\n        if (s != shown) {\n            shown = s;\n            char b[22] = \"Uptime: \"; int n = 8; char d[11]; int k = 0; uint32_t v = s;\n            do { d[k++] = (char)('0' + v % 10); v /= 10; } while (v);\n            while (k) b[n++] = d[--k];\n            b[n++] = ' '; b[n++] = 's'; b[n++] = ' '; b[n++] = ' '; b[n] = 0;\n            oled_text(6, 0, b);\n        }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"oled1","type":"oled","x":340,"y":200,"attrs":{"color":"white","i2c-address":"0x3C","height":"64"}}],"wires":[["oled1:GND","bluepill:GND.3","black"],["oled1:VCC","bluepill:3V3.2","red"],["oled1:SCL","bluepill:PB10","green"],["oled1:SDA","bluepill:PB11","blue"]]}},{"id":"oled_anim","title":"OLED 128x64: animation at 400 kHz (fast mode)","src":"/* SSD1306 OLED animation: bouncing ball, scrolling graph and an FPS counter.\n   Full-frame updates from a 1 KB framebuffer, I2C2 (SCL = PB10, SDA = PB11) in fast mode (about 380 kHz), horizontal addressing mode. */\n#include <stdint.h>\n#include \"stm32f1.h\"\n\nstatic const uint8_t font5x7[95][5] = {   /* ASCII 32..126, one byte per column, bit 0 = top row */\n    {0x00,0x00,0x00,0x00,0x00}, {0x00,0x00,0x5f,0x00,0x00}, {0x00,0x07,0x00,0x07,0x00}, {0x14,0x7f,0x14,0x7f,0x14},\n    {0x24,0x2a,0x7f,0x2a,0x12}, {0x23,0x13,0x08,0x64,0x62}, {0x36,0x49,0x56,0x20,0x50}, {0x00,0x08,0x07,0x03,0x00},\n    {0x00,0x1c,0x22,0x41,0x00}, {0x00,0x41,0x22,0x1c,0x00}, {0x2a,0x1c,0x7f,0x1c,0x2a}, {0x08,0x08,0x3e,0x08,0x08},\n    {0x00,0x80,0x70,0x30,0x00}, {0x08,0x08,0x08,0x08,0x08}, {0x00,0x00,0x60,0x60,0x00}, {0x20,0x10,0x08,0x04,0x02},\n    {0x3e,0x51,0x49,0x45,0x3e}, {0x00,0x42,0x7f,0x40,0x00}, {0x72,0x49,0x49,0x49,0x46}, {0x21,0x41,0x49,0x4d,0x33},\n    {0x18,0x14,0x12,0x7f,0x10}, {0x27,0x45,0x45,0x45,0x39}, {0x3c,0x4a,0x49,0x49,0x31}, {0x41,0x21,0x11,0x09,0x07},\n    {0x36,0x49,0x49,0x49,0x36}, {0x46,0x49,0x49,0x29,0x1e}, {0x00,0x00,0x14,0x00,0x00}, {0x00,0x40,0x34,0x00,0x00},\n    {0x00,0x08,0x14,0x22,0x41}, {0x14,0x14,0x14,0x14,0x14}, {0x00,0x41,0x22,0x14,0x08}, {0x02,0x01,0x59,0x09,0x06},\n    {0x3e,0x41,0x5d,0x59,0x4e}, {0x7c,0x12,0x11,0x12,0x7c}, {0x7f,0x49,0x49,0x49,0x36}, {0x3e,0x41,0x41,0x41,0x22},\n    {0x7f,0x41,0x41,0x41,0x3e}, {0x7f,0x49,0x49,0x49,0x41}, {0x7f,0x09,0x09,0x09,0x01}, {0x3e,0x41,0x41,0x51,0x73},\n    {0x7f,0x08,0x08,0x08,0x7f}, {0x00,0x41,0x7f,0x41,0x00}, {0x20,0x40,0x41,0x3f,0x01}, {0x7f,0x08,0x14,0x22,0x41},\n    {0x7f,0x40,0x40,0x40,0x40}, {0x7f,0x02,0x1c,0x02,0x7f}, {0x7f,0x04,0x08,0x10,0x7f}, {0x3e,0x41,0x41,0x41,0x3e},\n    {0x7f,0x09,0x09,0x09,0x06}, {0x3e,0x41,0x51,0x21,0x5e}, {0x7f,0x09,0x19,0x29,0x46}, {0x26,0x49,0x49,0x49,0x32},\n    {0x03,0x01,0x7f,0x01,0x03}, {0x3f,0x40,0x40,0x40,0x3f}, {0x1f,0x20,0x40,0x20,0x1f}, {0x3f,0x40,0x38,0x40,0x3f},\n    {0x63,0x14,0x08,0x14,0x63}, {0x03,0x04,0x78,0x04,0x03}, {0x61,0x59,0x49,0x4d,0x43}, {0x00,0x7f,0x41,0x41,0x41},\n    {0x02,0x04,0x08,0x10,0x20}, {0x00,0x41,0x41,0x7f,0x00}, {0x04,0x02,0x01,0x02,0x04}, {0x40,0x40,0x40,0x40,0x40},\n    {0x00,0x03,0x07,0x08,0x00}, {0x20,0x54,0x54,0x78,0x40}, {0x7f,0x28,0x44,0x44,0x38}, {0x38,0x44,0x44,0x44,0x28},\n    {0x38,0x44,0x44,0x28,0x7f}, {0x38,0x54,0x54,0x54,0x18}, {0x00,0x08,0x7e,0x09,0x02}, {0x18,0xa4,0xa4,0x9c,0x78},\n    {0x7f,0x08,0x04,0x04,0x78}, {0x00,0x44,0x7d,0x40,0x00}, {0x20,0x40,0x40,0x3d,0x00}, {0x7f,0x10,0x28,0x44,0x00},\n    {0x00,0x41,0x7f,0x40,0x00}, {0x7c,0x04,0x78,0x04,0x78}, {0x7c,0x08,0x04,0x04,0x78}, {0x38,0x44,0x44,0x44,0x38},\n    {0xfc,0x18,0x24,0x24,0x18}, {0x18,0x24,0x24,0x18,0xfc}, {0x7c,0x08,0x04,0x04,0x08}, {0x48,0x54,0x54,0x54,0x24},\n    {0x04,0x04,0x3f,0x44,0x24}, {0x3c,0x40,0x40,0x20,0x7c}, {0x1c,0x20,0x40,0x20,0x1c}, {0x3c,0x40,0x30,0x40,0x3c},\n    {0x44,0x28,0x10,0x28,0x44}, {0x4c,0x90,0x90,0x90,0x7c}, {0x44,0x64,0x54,0x4c,0x44}, {0x00,0x08,0x36,0x41,0x00},\n    {0x00,0x00,0x77,0x00,0x00}, {0x00,0x41,0x36,0x08,0x00}, {0x02,0x01,0x02,0x04,0x02},\n};\n#define OLED_ADDR 0x3C\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\nstatic uint8_t fb[1024];\n\nstatic void i2c_init(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPBEN | RCC_APB2ENR_AFIOEN;\n    RCC->APB1ENR |= RCC_APB1ENR_I2C2EN;\n    gpio_cfg(GPIOB, 10, GPIO_AF_OD_50MHZ);\n    gpio_cfg(GPIOB, 11, GPIO_AF_OD_50MHZ);\n    I2C2->CR2 = 8;\n    I2C2->CCR = I2C_CCR_FS | 7;                    /* fast mode: 3 x 7 / 8 MHz = 2.6 us period */\n    I2C2->TRISE = 3;\n    I2C2->CR1 = I2C_CR1_PE;\n}\nstatic int i2c_start(uint8_t addr_rw) {              /* returns 1 on ACK, 0 on NACK */\n    I2C2->CR1 |= I2C_CR1_START;\n    while (!(I2C2->SR1 & I2C_SR1_SB));\n    I2C2->DR = addr_rw;\n    for (;;) {\n        uint32_t s = I2C2->SR1;\n        if (s & I2C_SR1_ADDR) { (void)I2C2->SR2; return 1; }\n        if (s & I2C_SR1_AF) { I2C2->SR1 &= ~I2C_SR1_AF; I2C2->CR1 |= I2C_CR1_STOP; while (I2C2->CR1 & I2C_CR1_STOP); return 0; }\n    }\n}\nstatic void i2c_put(uint8_t b) { while (!(I2C2->SR1 & I2C_SR1_TXE)); I2C2->DR = b; }\nstatic void i2c_stop(void) { while (!(I2C2->SR1 & I2C_SR1_BTF)); I2C2->CR1 |= I2C_CR1_STOP; while (I2C2->CR1 & I2C_CR1_STOP); }\n\nstatic void oled_cmds(const uint8_t *c, int n) {\n    if (!i2c_start(OLED_ADDR << 1)) return;\n    i2c_put(0x00); while (n--) i2c_put(*c++); i2c_stop();\n}\nstatic void oled_flush(void) {\n    static const uint8_t win[] = { 0x21, 0, 127, 0x22, 0, 7 };   /* column 0..127, page 0..7 */\n    oled_cmds(win, sizeof win);\n    if (!i2c_start(OLED_ADDR << 1)) return;\n    i2c_put(0x40);\n    for (int i = 0; i < 1024; i++) i2c_put(fb[i]);\n    i2c_stop();\n}\nstatic void px(int x, int y) { if ((unsigned)x < 128 && (unsigned)y < 64) fb[(y >> 3) * 128 + x] |= (uint8_t)(1u << (y & 7)); }\nstatic void line(int x0, int y0, int x1, int y1) {\n    int dx = x1 > x0 ? x1 - x0 : x0 - x1, sx = x0 < x1 ? 1 : -1, dy = y1 > y0 ? y0 - y1 : y1 - y0, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n    for (;;) { px(x0, y0); if (x0 == x1 && y0 == y1) break; int e2 = 2 * e; if (e2 >= dy) { e += dy; x0 += sx; } if (e2 <= dx) { e += dx; y0 += sy; } }\n}\nstatic void disc(int cx, int cy, int r) { for (int y = -r; y <= r; y++) for (int x = -r; x <= r; x++) if (x * x + y * y <= r * r + r / 2) px(cx + x, cy + y); }\nstatic void text(int x, int y, const char *s) {\n    for (; *s; s++, x += 6) { const uint8_t *g = font5x7[(*s - 32) % 95]; for (int c = 0; c < 5; c++) for (int r = 0; r < 8; r++) if ((g[c] >> r) & 1) px(x + c, y + r); }\n}\nstatic void num(int x, int y, uint32_t v) { char d[11]; int k = 0; do { d[k++] = (char)('0' + v % 10); v /= 10; } while (v); char b[12]; int n = 0; while (k) b[n++] = d[--k]; b[n] = 0; text(x, y, b); }\n\nint main(void) {\n    static const uint8_t init[] = { 0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40, 0x8D, 0x14, 0x20, 0x00, 0xA1, 0xC8, 0xDA, 0x12, 0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6, 0xAF };\n    i2c_init();\n    SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7;\n    oled_cmds(init, sizeof init);\n    int bx = 20, by = 30, vx = 2, vy = 1; static uint8_t hist[128]; uint32_t frames = 0, fps = 0, t0 = 0, next = 0, tick = 0;\n    for (;;) {\n        while (ms < next) { }\n        next = ms + 40;                                             /* about 25 frames per second */\n        for (int i = 0; i < 1024; i++) fb[i] = 0;\n        bx += vx; by += vy; if (bx < 4 || bx > 123) vx = -vx; if (by < 18 || by > 43) vy = -vy;\n        for (int x = 0; x < 128; x++) { px(x, 63); if ((x & 7) == 0) px(x, 62); }\n        line(0, 16, 127, 16);\n        text(0, 4, \"PinForge OLED\"); num(88, 4, fps); text(106, 4, \"fps\");\n        disc(bx, by, 4);\n        hist[tick & 127] = (uint8_t)((by - 18) * 12 / 25);              /* history of the ball's height */\n        tick++;\n        for (int x = 1; x < 128; x++) line(x - 1, 60 - hist[(tick + x - 1) & 127], x, 60 - hist[(tick + x) & 127]);\n        oled_flush(); frames++;\n        if (ms - t0 >= 1000) { fps = frames * 1000 / (ms - t0); frames = 0; t0 = ms; }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"oled1","type":"oled","x":340,"y":200,"attrs":{"color":"dual","i2c-address":"0x3C","height":"64"}}],"wires":[["oled1:GND","bluepill:GND.3","black"],["oled1:VCC","bluepill:3V3.2","red"],["oled1:SCL","bluepill:PB10","green"],["oled1:SDA","bluepill:PB11","blue"]]}},{"id":"i2c_scan","title":"I2C scanner for I2C1 + I2C2 (Serial Monitor)","src":"/* I2C bus scanner: probes every 7-bit address on I2C1 (PB6 = SCL, PB7 = SDA) and I2C2 (PB10 = SCL, PB11 = SDA)\n   and prints the devices that answer on USART1 (PA9, 115200 baud): open the Serial Monitor.\n\n   Like on real hardware, a bus needs pull-up resistors on SCL and SDA. Most breakout modules carry them; if nothing\n   pulls the lines up, the peripheral cannot finish a transfer, so every wait below has a timeout and a dead bus is\n   reported instead of hanging the program. */\n#include <stdint.h>\n#include \"stm32f1.h\"\n\nstatic void putc_(char c) { while (!(USART1->SR & 0x80)); USART1->DR = (uint32_t)c; }\nstatic void puts_(const char *s) { while (*s) putc_(*s++); }\nstatic void hex2(unsigned v) { putc_(\"0123456789ABCDEF\"[(v >> 4) & 15]); putc_(\"0123456789ABCDEF\"[v & 15]); }\n\n#define TIMEOUT 20000\nstatic int wait(I2C_TypeDef *i2c, uint32_t flags) {      /* 1 = flag set, 0 = timeout */\n    for (int n = TIMEOUT; n; n--) if (i2c->SR1 & flags) return 1;\n    return 0;\n}\nstatic void reset(I2C_TypeDef *i2c) { i2c->CR1 &= ~I2C_CR1_PE; i2c->CR1 |= I2C_CR1_PE; }\nstatic void i2c_init(I2C_TypeDef *i2c) { i2c->CR2 = 8; i2c->CCR = 40; i2c->TRISE = 9; i2c->CR1 = I2C_CR1_PE; }   /* 100 kHz at 8 MHz */\n\n/* 1 = ACK, 0 = NACK, -1 = bus fault (SCL never rises, or arbitration lost) */\nstatic int probe(I2C_TypeDef *i2c, uint8_t addr7) {\n    i2c->CR1 |= I2C_CR1_START;\n    if (!wait(i2c, I2C_SR1_SB)) { i2c->CR1 &= ~I2C_CR1_START; reset(i2c); return -1; }\n    i2c->DR = (uint8_t)(addr7 << 1);                     /* write, address only */\n    for (int n = TIMEOUT; n; n--) {\n        uint32_t s = i2c->SR1;\n        if (s & I2C_SR1_ADDR) { (void)i2c->SR2; i2c->CR1 |= I2C_CR1_STOP; while (i2c->CR1 & I2C_CR1_STOP); return 1; }\n        if (s & I2C_SR1_AF)   { i2c->SR1 &= ~I2C_SR1_AF; i2c->CR1 |= I2C_CR1_STOP; while (i2c->CR1 & I2C_CR1_STOP); return 0; }\n        if (s & (1u << 9))    { reset(i2c); return -1; } /* ARLO: SDA could not be released */\n    }\n    reset(i2c); return -1;                               /* SCL held low: no pull-up on SCL */\n}\nstatic void scan(I2C_TypeDef *i2c, const char *name) {\n    int found = 0;\n    puts_(name); puts_(\":\\r\\n\");\n    for (unsigned a = 1; a < 127; a++) {\n        int r = probe(i2c, (uint8_t)a);\n        if (r < 0) { puts_(\"  bus fault: no pull-up resistors on SCL/SDA?\\r\\n\"); return; }\n        if (r) { puts_(\"  found device at 0x\"); hex2(a); puts_(\"\\r\\n\"); found++; }\n    }\n    if (!found) puts_(\"  no devices\\r\\n\");\n}\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_IOPBEN | RCC_APB2ENR_AFIOEN | RCC_APB2ENR_USART1EN;\n    RCC->APB1ENR |= RCC_APB1ENR_I2C1EN | RCC_APB1ENR_I2C2EN;\n    gpio_cfg(GPIOA, 9, GPIO_AF_PP_2MHZ);\n    gpio_cfg(GPIOB, 6, GPIO_AF_OD_50MHZ);  gpio_cfg(GPIOB, 7, GPIO_AF_OD_50MHZ);\n    gpio_cfg(GPIOB, 10, GPIO_AF_OD_50MHZ); gpio_cfg(GPIOB, 11, GPIO_AF_OD_50MHZ);\n    USART1->BRR = 8000000 / 115200; USART1->CR1 = (1u << 13) | (1u << 3);\n    i2c_init(I2C1); i2c_init(I2C2);\n    puts_(\"I2C scanner\\r\\n\");\n    scan(I2C1, \"I2C1 (SCL=PB6, SDA=PB7)\");\n    scan(I2C2, \"I2C2 (SCL=PB10, SDA=PB11)\");\n    puts_(\"done.\\r\\n\");\n    for (;;);\n}\n","b64":"","circuit":{"parts":[{"id":"oled1","type":"oled","x":340,"y":200,"attrs":{"color":"white","i2c-address":"0x3C","height":"64"}}],"wires":[["oled1:GND","bluepill:GND.3","black"],["oled1:VCC","bluepill:3V3.2","red"],["oled1:SCL","bluepill:PB10","green"],["oled1:SDA","bluepill:PB11","blue"]]}},{"id":"mpu6050_read","title":"MPU-6050 accel/gyro/temperature (Serial Monitor)","src":"/* MPU-6050 accelerometer + gyroscope + thermometer on I2C2 (SCL = PB10, SDA = PB11, address 0x68 with AD0 open).\n   Prints a reading twice a second on the Serial Monitor (USART1, PA9, 115200 baud).\n   While it runs, change the accel / gyro / temperature values in the sensor's inspector panel.\n   The chip powers up asleep (PWR_MGMT_1 = 0x40): it must be woken before the data registers update. */\n#include <stdint.h>\n#include \"stm32f1.h\"\n\nstatic volatile uint32_t ms; void SysTick_Handler(void) { ms++; }\nstatic void delay_ms(uint32_t d) { uint32_t t = ms + d; while ((int32_t)(ms - t) < 0) { } }\nstatic void uart_init(void) { RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_USART1EN; gpio_cfg(GPIOA, 9, GPIO_AF_PP_2MHZ); USART1->BRR = 8000000 / 115200; USART1->CR1 = (1u << 13) | (1u << 3); SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7; }\nstatic void putc_(char c) { while (!(USART1->SR & 0x80)); USART1->DR = (uint32_t)c; }\nstatic void puts_(const char *s) { while (*s) putc_(*s++); }\nstatic void put_fixed(int32_t v, int dec, int width) {      /* v has `dec` implied decimals; right-aligned in `width` characters */\n    char b[16], t[12];\n    int n = 0, k = 0, neg = v < 0;\n    uint32_t u = (uint32_t)(neg ? -v : v), p = 1;\n    for (int i = 0; i < dec; i++) p *= 10;\n    uint32_t ip = u / p, fp = u % p;\n    do { t[k++] = (char)('0' + ip % 10); ip /= 10; } while (ip);\n    if (neg) { b[n++] = '-'; }\n    while (k) { b[n++] = t[--k]; }\n    if (dec) {\n        b[n++] = '.';\n        for (int i = dec - 1; i >= 0; i--) { uint32_t q = 1; for (int j = 0; j < i; j++) q *= 10; b[n++] = (char)('0' + (fp / q) % 10); }\n    }\n    for (int i = n; i < width; i++) { putc_(' '); }\n    for (int i = 0; i < n; i++) { putc_(b[i]); }\n}\n\n/* ---- minimal I2C2 master driver (PB10 = SCL, PB11 = SDA). Every wait has a timeout, so a missing pull-up or a\n   wrong address is reported as an error code instead of hanging the program.  0 = ok, 1 = NACK, 2 = bus fault ---- */\n#define TIMEOUT 30000\nstatic int wait_flag(uint32_t f) {\n    for (int n = TIMEOUT; n; n--) { uint32_t s = I2C2->SR1; if (s & f) return 0; if (s & I2C_SR1_AF) return 1; if (s & (1u << 9)) return 2; }\n    return 2;\n}\nstatic void bus_reset(void) { I2C2->CR1 &= ~I2C_CR1_PE; I2C2->CR1 |= I2C_CR1_PE; }\nstatic void stop(void) { I2C2->CR1 |= I2C_CR1_STOP; for (int n = TIMEOUT; n && (I2C2->CR1 & I2C_CR1_STOP); n--); }\nstatic int fail(int r) { if (r == 1) { I2C2->SR1 &= ~I2C_SR1_AF; stop(); } else bus_reset(); return r; }\nstatic void i2c_init(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPBEN | RCC_APB2ENR_AFIOEN; RCC->APB1ENR |= RCC_APB1ENR_I2C2EN;\n    gpio_cfg(GPIOB, 10, GPIO_AF_OD_50MHZ); gpio_cfg(GPIOB, 11, GPIO_AF_OD_50MHZ);\n    I2C2->CR2 = 8; I2C2->CCR = 40; I2C2->TRISE = 9; I2C2->CR1 = I2C_CR1_PE;                 /* 100 kHz at 8 MHz */\n}\nstatic int i2c_write(uint8_t a7, const uint8_t *d, int n, int with_stop) {\n    int r; I2C2->CR1 |= I2C_CR1_START;\n    if ((r = wait_flag(I2C_SR1_SB))) return fail(r);\n    I2C2->DR = (uint8_t)(a7 << 1);\n    if ((r = wait_flag(I2C_SR1_ADDR))) return fail(r);\n    (void)I2C2->SR2;\n    for (int i = 0; i < n; i++) { if ((r = wait_flag(I2C_SR1_TXE))) return fail(r); I2C2->DR = d[i]; }\n    if (n && (r = wait_flag(I2C_SR1_BTF))) return fail(r);\n    if (with_stop) stop();\n    return 0;\n}\nstatic int i2c_read(uint8_t a7, uint8_t *d, int n) {          /* the three receive sequences of RM0008 */\n    int r; I2C2->CR1 |= I2C_CR1_ACK; if (n == 2) I2C2->CR1 |= I2C_CR1_POS;\n    I2C2->CR1 |= I2C_CR1_START;\n    if ((r = wait_flag(I2C_SR1_SB))) { I2C2->CR1 &= ~I2C_CR1_POS; return fail(r); }\n    I2C2->DR = (uint8_t)((a7 << 1) | 1);\n    if ((r = wait_flag(I2C_SR1_ADDR))) { I2C2->CR1 &= ~I2C_CR1_POS; return fail(r); }\n    if (n == 1) { I2C2->CR1 &= ~I2C_CR1_ACK; (void)I2C2->SR2; I2C2->CR1 |= I2C_CR1_STOP; if ((r = wait_flag(I2C_SR1_RXNE))) return fail(r); d[0] = (uint8_t)I2C2->DR; }\n    else if (n == 2) { (void)I2C2->SR2; I2C2->CR1 &= ~I2C_CR1_ACK; if ((r = wait_flag(I2C_SR1_BTF))) return fail(r); I2C2->CR1 |= I2C_CR1_STOP; d[0] = (uint8_t)I2C2->DR; d[1] = (uint8_t)I2C2->DR; }\n    else {\n        (void)I2C2->SR2;\n        while (n > 3) { if ((r = wait_flag(I2C_SR1_BTF))) return fail(r); *d++ = (uint8_t)I2C2->DR; n--; }\n        if ((r = wait_flag(I2C_SR1_BTF))) { return fail(r); }\n        I2C2->CR1 &= ~I2C_CR1_ACK; *d++ = (uint8_t)I2C2->DR; I2C2->CR1 |= I2C_CR1_STOP;\n        *d++ = (uint8_t)I2C2->DR;\n        if ((r = wait_flag(I2C_SR1_RXNE))) { return fail(r); }\n        *d++ = (uint8_t)I2C2->DR;\n    }\n    for (int k = TIMEOUT; k && (I2C2->CR1 & I2C_CR1_STOP); k--);\n    I2C2->CR1 &= ~I2C_CR1_POS; return 0;\n}\nstatic int read_regs(uint8_t a7, uint8_t reg, uint8_t *d, int n) {      /* write the register number, repeated START, read n bytes */\n    int r = i2c_write(a7, &reg, 1, 0); if (r) return r; return i2c_read(a7, d, n);\n}\nstatic int write_reg(uint8_t a7, uint8_t reg, uint8_t v) { uint8_t b[2] = { reg, v }; return i2c_write(a7, b, 2, 1); }\n\n#define MPU 0x68\nint main(void) {\n    uart_init(); i2c_init();\n    puts_(\"MPU-6050\\r\\n\");\n    uint8_t id = 0;\n    if (read_regs(MPU, 0x75, &id, 1) || id != 0x68) { puts_(\"sensor not found (check wiring, address and supply)\\r\\n\"); for (;;) { } }\n    write_reg(MPU, 0x6B, 0x00);                         /* wake up: clear SLEEP */\n    write_reg(MPU, 0x1C, 0x00);                         /* accel +-2 g  (16384 LSB per g) */\n    write_reg(MPU, 0x1B, 0x00);                         /* gyro +-250 dps (131 LSB per dps) */\n    delay_ms(100);                                      /* accel needs 20 ms, gyro 35 ms to start */\n    for (;;) {\n        uint8_t b[14];\n        if (read_regs(MPU, 0x3B, b, 14)) {\n            puts_(\"read failed\\r\\n\"); delay_ms(500); continue;\n        }\n        int16_t ax = (int16_t)((b[0] << 8) | b[1]), ay = (int16_t)((b[2] << 8) | b[3]), az = (int16_t)((b[4] << 8) | b[5]);\n        int16_t t = (int16_t)((b[6] << 8) | b[7]), gx = (int16_t)((b[8] << 8) | b[9]), gy = (int16_t)((b[10] << 8) | b[11]), gz = (int16_t)((b[12] << 8) | b[13]);\n        puts_(\"accel g: \"); put_fixed(ax * 1000 / 16384, 3, 7); put_fixed(ay * 1000 / 16384, 3, 7); put_fixed(az * 1000 / 16384, 3, 7);\n        puts_(\"   temp C: \"); put_fixed(t * 100 / 340 + 3653, 2, 6);\n        puts_(\"   gyro dps: \"); put_fixed(gx * 10 / 131, 1, 7); put_fixed(gy * 10 / 131, 1, 7); put_fixed(gz * 10 / 131, 1, 7); puts_(\"\\r\\n\");\n        delay_ms(500);\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"mpu1","type":"mpu6050","x":340,"y":200,"attrs":{"ax":"0","ay":"0","az":"1","gx":"0","gy":"0","gz":"0","temp":"25"}}],"wires":[["mpu1:GND","bluepill:GND.3","black"],["mpu1:VCC","bluepill:3V3.2","red"],["mpu1:SCL","bluepill:PB10","green"],["mpu1:SDA","bluepill:PB11","blue"]]}},{"id":"bme280_oled","title":"BME280 weather station on an OLED (2 devices, 1 bus)","src":"/* Weather station: BME280 (temperature, pressure, humidity) and an SSD1306 OLED share the same I2C2 bus\n   (SCL = PB10, SDA = PB11). The BME280 is read with Bosch's own integer compensation formulas from its datasheet.\n   Change temperature / pressure / humidity in the BME280's inspector while it runs. */\n#include <stdint.h>\n#include \"stm32f1.h\"\n\nstatic const uint8_t font5x7[95][5] = {   /* ASCII 32..126, one byte per column, bit 0 = top row */\n    {0x00,0x00,0x00,0x00,0x00}, {0x00,0x00,0x5f,0x00,0x00}, {0x00,0x07,0x00,0x07,0x00}, {0x14,0x7f,0x14,0x7f,0x14},\n    {0x24,0x2a,0x7f,0x2a,0x12}, {0x23,0x13,0x08,0x64,0x62}, {0x36,0x49,0x56,0x20,0x50}, {0x00,0x08,0x07,0x03,0x00},\n    {0x00,0x1c,0x22,0x41,0x00}, {0x00,0x41,0x22,0x1c,0x00}, {0x2a,0x1c,0x7f,0x1c,0x2a}, {0x08,0x08,0x3e,0x08,0x08},\n    {0x00,0x80,0x70,0x30,0x00}, {0x08,0x08,0x08,0x08,0x08}, {0x00,0x00,0x60,0x60,0x00}, {0x20,0x10,0x08,0x04,0x02},\n    {0x3e,0x51,0x49,0x45,0x3e}, {0x00,0x42,0x7f,0x40,0x00}, {0x72,0x49,0x49,0x49,0x46}, {0x21,0x41,0x49,0x4d,0x33},\n    {0x18,0x14,0x12,0x7f,0x10}, {0x27,0x45,0x45,0x45,0x39}, {0x3c,0x4a,0x49,0x49,0x31}, {0x41,0x21,0x11,0x09,0x07},\n    {0x36,0x49,0x49,0x49,0x36}, {0x46,0x49,0x49,0x29,0x1e}, {0x00,0x00,0x14,0x00,0x00}, {0x00,0x40,0x34,0x00,0x00},\n    {0x00,0x08,0x14,0x22,0x41}, {0x14,0x14,0x14,0x14,0x14}, {0x00,0x41,0x22,0x14,0x08}, {0x02,0x01,0x59,0x09,0x06},\n    {0x3e,0x41,0x5d,0x59,0x4e}, {0x7c,0x12,0x11,0x12,0x7c}, {0x7f,0x49,0x49,0x49,0x36}, {0x3e,0x41,0x41,0x41,0x22},\n    {0x7f,0x41,0x41,0x41,0x3e}, {0x7f,0x49,0x49,0x49,0x41}, {0x7f,0x09,0x09,0x09,0x01}, {0x3e,0x41,0x41,0x51,0x73},\n    {0x7f,0x08,0x08,0x08,0x7f}, {0x00,0x41,0x7f,0x41,0x00}, {0x20,0x40,0x41,0x3f,0x01}, {0x7f,0x08,0x14,0x22,0x41},\n    {0x7f,0x40,0x40,0x40,0x40}, {0x7f,0x02,0x1c,0x02,0x7f}, {0x7f,0x04,0x08,0x10,0x7f}, {0x3e,0x41,0x41,0x41,0x3e},\n    {0x7f,0x09,0x09,0x09,0x06}, {0x3e,0x41,0x51,0x21,0x5e}, {0x7f,0x09,0x19,0x29,0x46}, {0x26,0x49,0x49,0x49,0x32},\n    {0x03,0x01,0x7f,0x01,0x03}, {0x3f,0x40,0x40,0x40,0x3f}, {0x1f,0x20,0x40,0x20,0x1f}, {0x3f,0x40,0x38,0x40,0x3f},\n    {0x63,0x14,0x08,0x14,0x63}, {0x03,0x04,0x78,0x04,0x03}, {0x61,0x59,0x49,0x4d,0x43}, {0x00,0x7f,0x41,0x41,0x41},\n    {0x02,0x04,0x08,0x10,0x20}, {0x00,0x41,0x41,0x7f,0x00}, {0x04,0x02,0x01,0x02,0x04}, {0x40,0x40,0x40,0x40,0x40},\n    {0x00,0x03,0x07,0x08,0x00}, {0x20,0x54,0x54,0x78,0x40}, {0x7f,0x28,0x44,0x44,0x38}, {0x38,0x44,0x44,0x44,0x28},\n    {0x38,0x44,0x44,0x28,0x7f}, {0x38,0x54,0x54,0x54,0x18}, {0x00,0x08,0x7e,0x09,0x02}, {0x18,0xa4,0xa4,0x9c,0x78},\n    {0x7f,0x08,0x04,0x04,0x78}, {0x00,0x44,0x7d,0x40,0x00}, {0x20,0x40,0x40,0x3d,0x00}, {0x7f,0x10,0x28,0x44,0x00},\n    {0x00,0x41,0x7f,0x40,0x00}, {0x7c,0x04,0x78,0x04,0x78}, {0x7c,0x08,0x04,0x04,0x78}, {0x38,0x44,0x44,0x44,0x38},\n    {0xfc,0x18,0x24,0x24,0x18}, {0x18,0x24,0x24,0x18,0xfc}, {0x7c,0x08,0x04,0x04,0x08}, {0x48,0x54,0x54,0x54,0x24},\n    {0x04,0x04,0x3f,0x44,0x24}, {0x3c,0x40,0x40,0x20,0x7c}, {0x1c,0x20,0x40,0x20,0x1c}, {0x3c,0x40,0x30,0x40,0x3c},\n    {0x44,0x28,0x10,0x28,0x44}, {0x4c,0x90,0x90,0x90,0x7c}, {0x44,0x64,0x54,0x4c,0x44}, {0x00,0x08,0x36,0x41,0x00},\n    {0x00,0x00,0x77,0x00,0x00}, {0x00,0x41,0x36,0x08,0x00}, {0x02,0x01,0x02,0x04,0x02},\n};\nstatic volatile uint32_t ms; void SysTick_Handler(void) { ms++; }\nstatic void delay_ms(uint32_t d) { uint32_t t = ms + d; while ((int32_t)(ms - t) < 0) { } }\nstatic void uart_init(void) { RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_USART1EN; gpio_cfg(GPIOA, 9, GPIO_AF_PP_2MHZ); USART1->BRR = 8000000 / 115200; USART1->CR1 = (1u << 13) | (1u << 3); SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7; }\nstatic void putc_(char c) { while (!(USART1->SR & 0x80)); USART1->DR = (uint32_t)c; }\nstatic void puts_(const char *s) { while (*s) putc_(*s++); }\n\n/* ---- minimal I2C2 master driver (PB10 = SCL, PB11 = SDA). Every wait has a timeout, so a missing pull-up or a\n   wrong address is reported as an error code instead of hanging the program.  0 = ok, 1 = NACK, 2 = bus fault ---- */\n#define TIMEOUT 30000\nstatic int wait_flag(uint32_t f) {\n    for (int n = TIMEOUT; n; n--) { uint32_t s = I2C2->SR1; if (s & f) return 0; if (s & I2C_SR1_AF) return 1; if (s & (1u << 9)) return 2; }\n    return 2;\n}\nstatic void bus_reset(void) { I2C2->CR1 &= ~I2C_CR1_PE; I2C2->CR1 |= I2C_CR1_PE; }\nstatic void stop(void) { I2C2->CR1 |= I2C_CR1_STOP; for (int n = TIMEOUT; n && (I2C2->CR1 & I2C_CR1_STOP); n--); }\nstatic int fail(int r) { if (r == 1) { I2C2->SR1 &= ~I2C_SR1_AF; stop(); } else bus_reset(); return r; }\nstatic void i2c_init(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPBEN | RCC_APB2ENR_AFIOEN; RCC->APB1ENR |= RCC_APB1ENR_I2C2EN;\n    gpio_cfg(GPIOB, 10, GPIO_AF_OD_50MHZ); gpio_cfg(GPIOB, 11, GPIO_AF_OD_50MHZ);\n    I2C2->CR2 = 8; I2C2->CCR = 40; I2C2->TRISE = 9; I2C2->CR1 = I2C_CR1_PE;                 /* 100 kHz at 8 MHz */\n}\nstatic int i2c_write(uint8_t a7, const uint8_t *d, int n, int with_stop) {\n    int r; I2C2->CR1 |= I2C_CR1_START;\n    if ((r = wait_flag(I2C_SR1_SB))) return fail(r);\n    I2C2->DR = (uint8_t)(a7 << 1);\n    if ((r = wait_flag(I2C_SR1_ADDR))) return fail(r);\n    (void)I2C2->SR2;\n    for (int i = 0; i < n; i++) { if ((r = wait_flag(I2C_SR1_TXE))) return fail(r); I2C2->DR = d[i]; }\n    if (n && (r = wait_flag(I2C_SR1_BTF))) return fail(r);\n    if (with_stop) stop();\n    return 0;\n}\nstatic int i2c_read(uint8_t a7, uint8_t *d, int n) {          /* the three receive sequences of RM0008 */\n    int r; I2C2->CR1 |= I2C_CR1_ACK; if (n == 2) I2C2->CR1 |= I2C_CR1_POS;\n    I2C2->CR1 |= I2C_CR1_START;\n    if ((r = wait_flag(I2C_SR1_SB))) { I2C2->CR1 &= ~I2C_CR1_POS; return fail(r); }\n    I2C2->DR = (uint8_t)((a7 << 1) | 1);\n    if ((r = wait_flag(I2C_SR1_ADDR))) { I2C2->CR1 &= ~I2C_CR1_POS; return fail(r); }\n    if (n == 1) { I2C2->CR1 &= ~I2C_CR1_ACK; (void)I2C2->SR2; I2C2->CR1 |= I2C_CR1_STOP; if ((r = wait_flag(I2C_SR1_RXNE))) return fail(r); d[0] = (uint8_t)I2C2->DR; }\n    else if (n == 2) { (void)I2C2->SR2; I2C2->CR1 &= ~I2C_CR1_ACK; if ((r = wait_flag(I2C_SR1_BTF))) return fail(r); I2C2->CR1 |= I2C_CR1_STOP; d[0] = (uint8_t)I2C2->DR; d[1] = (uint8_t)I2C2->DR; }\n    else {\n        (void)I2C2->SR2;\n        while (n > 3) { if ((r = wait_flag(I2C_SR1_BTF))) return fail(r); *d++ = (uint8_t)I2C2->DR; n--; }\n        if ((r = wait_flag(I2C_SR1_BTF))) { return fail(r); }\n        I2C2->CR1 &= ~I2C_CR1_ACK; *d++ = (uint8_t)I2C2->DR; I2C2->CR1 |= I2C_CR1_STOP;\n        *d++ = (uint8_t)I2C2->DR;\n        if ((r = wait_flag(I2C_SR1_RXNE))) { return fail(r); }\n        *d++ = (uint8_t)I2C2->DR;\n    }\n    for (int k = TIMEOUT; k && (I2C2->CR1 & I2C_CR1_STOP); k--);\n    I2C2->CR1 &= ~I2C_CR1_POS; return 0;\n}\nstatic int read_regs(uint8_t a7, uint8_t reg, uint8_t *d, int n) {      /* write the register number, repeated START, read n bytes */\n    int r = i2c_write(a7, &reg, 1, 0); if (r) return r; return i2c_read(a7, d, n);\n}\nstatic int write_reg(uint8_t a7, uint8_t reg, uint8_t v) { uint8_t b[2] = { reg, v }; return i2c_write(a7, b, 2, 1); }\n\n#define OLED 0x3C\n#define BME  0x76\nstatic uint16_t T1, P1; static int16_t T2, T3, P2, P3, P4, P5, P6, P7, P8, P9, H2, H4, H5; static uint8_t H1, H3; static int8_t H6; static int32_t t_fine;\nstatic int32_t comp_T(int32_t a) { int32_t v1 = ((((a >> 3) - ((int32_t)T1 << 1))) * ((int32_t)T2)) >> 11; int32_t v2 = (((((a >> 4) - ((int32_t)T1)) * ((a >> 4) - ((int32_t)T1))) >> 12) * ((int32_t)T3)) >> 14; t_fine = v1 + v2; return (t_fine * 5 + 128) >> 8; }\nstatic uint32_t comp_P(int32_t a) {                       /* Pa x 256 */\n    int64_t v1 = ((int64_t)t_fine) - 128000, v2 = v1 * v1 * (int64_t)P6; v2 += ((v1 * (int64_t)P5) << 17); v2 += (((int64_t)P4) << 35);\n    v1 = ((v1 * v1 * (int64_t)P3) >> 8) + ((v1 * (int64_t)P2) << 12); v1 = (((((int64_t)1) << 47) + v1)) * ((int64_t)P1) >> 33; if (!v1) return 0;\n    int64_t p = 1048576 - a; p = (((p << 31) - v2) * 3125) / v1; v1 = (((int64_t)P9) * (p >> 13) * (p >> 13)) >> 25; v2 = (((int64_t)P8) * p) >> 19; return (uint32_t)(((p + v1 + v2) >> 8) + (((int64_t)P7) << 4));\n}\nstatic uint32_t comp_H(int32_t a) {                       /* %RH x 1024 */\n    int32_t v = (t_fine - 76800);\n    v = (((((a << 14) - (((int32_t)H4) << 20) - (((int32_t)H5) * v)) + 16384) >> 15) * (((((((v * ((int32_t)H6)) >> 10) * (((v * ((int32_t)H3)) >> 11) + 32768)) >> 10) + 2097152) * ((int32_t)H2) + 8192) >> 14));\n    v = (v - (((((v >> 15) * (v >> 15)) >> 7) * ((int32_t)H1)) >> 4)); v = (v < 0 ? 0 : v); v = (v > 419430400 ? 419430400 : v); return (uint32_t)(v >> 12);\n}\nstatic void oled_send(uint8_t ctl, const uint8_t *d, int n) { uint8_t b[130]; b[0] = ctl; for (int i = 0; i < n; i++) b[1 + i] = d[i]; i2c_write(OLED, b, n + 1, 1); }\nstatic void oled_init(void) {\n    static const uint8_t init[] = { 0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40, 0x8D, 0x14, 0x20, 0x02, 0xA1, 0xC8, 0xDA, 0x12, 0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6, 0xAF };\n    oled_send(0x00, init, sizeof init);\n}\nstatic void oled_text(int page, const char *s) {\n    uint8_t buf[128] = { 0 }; int n = 0; uint8_t pos[3] = { (uint8_t)(0xB0 | page), 0x00, 0x10 };\n    for (; *s && n + 6 <= 128; s++) { const uint8_t *g = font5x7[(*s - 32) % 95]; for (int i = 0; i < 5; i++) buf[n++] = g[i]; buf[n++] = 0; }\n    oled_send(0x00, pos, 3); oled_send(0x40, buf, 128);\n}\nstatic void fmt(char *o, const char *label, int32_t v, int dec, const char *unit) {    /* \"T:   25.00 C\" */\n    int n = 0, k = 0, m = 0, neg = v < 0;\n    char t[14], d[12];\n    while (*label) { o[n++] = *label++; }\n    uint32_t u = (uint32_t)(neg ? -v : v), p = 1;\n    for (int i = 0; i < dec; i++) p *= 10;\n    uint32_t ip = u / p, fp = u % p;\n    do { d[m++] = (char)('0' + ip % 10); ip /= 10; } while (ip);\n    if (neg) { t[k++] = '-'; }\n    while (m) { t[k++] = d[--m]; }\n    if (dec) {\n        t[k++] = '.';\n        for (int i = dec - 1; i >= 0; i--) { uint32_t q = 1; for (int j = 0; j < i; j++) q *= 10; t[k++] = (char)('0' + (fp / q) % 10); }\n    }\n    for (int i = k; i < 8; i++) { o[n++] = ' '; }\n    for (int i = 0; i < k; i++) { o[n++] = t[i]; }\n    o[n++] = ' ';\n    while (*unit) { o[n++] = *unit++; }\n    o[n] = 0;\n}\nint main(void) {\n    uart_init(); i2c_init(); oled_init();\n    oled_text(0, \"BME280 weather\");\n    uint8_t id = 0;\n    if (read_regs(BME, 0xD0, &id, 1)) {\n        oled_text(2, \"BME280 not found\"); puts_(\"BME280 not found\\r\\n\");\n        for (;;) { }\n    }\n    int bme = (id == 0x60); puts_(bme ? \"BME280\\r\\n\" : \"BMP280 (no humidity)\\r\\n\");\n    uint8_t c[24]; read_regs(BME, 0x88, c, 24);\n    T1 = (uint16_t)(c[0] | c[1] << 8); T2 = (int16_t)(c[2] | c[3] << 8); T3 = (int16_t)(c[4] | c[5] << 8); P1 = (uint16_t)(c[6] | c[7] << 8);\n    P2 = (int16_t)(c[8] | c[9] << 8); P3 = (int16_t)(c[10] | c[11] << 8); P4 = (int16_t)(c[12] | c[13] << 8); P5 = (int16_t)(c[14] | c[15] << 8);\n    P6 = (int16_t)(c[16] | c[17] << 8); P7 = (int16_t)(c[18] | c[19] << 8); P8 = (int16_t)(c[20] | c[21] << 8); P9 = (int16_t)(c[22] | c[23] << 8);\n    if (bme) { uint8_t h[7]; read_regs(BME, 0xA1, h, 1); H1 = h[0]; read_regs(BME, 0xE1, h, 7);\n        H2 = (int16_t)(h[0] | h[1] << 8); H3 = h[2]; H4 = (int16_t)(((int8_t)h[3] * 16) | (h[4] & 0x0F)); H5 = (int16_t)(((int8_t)h[5] * 16) | (h[4] >> 4)); H6 = (int8_t)h[6]; }\n    for (;;) {\n        if (bme) write_reg(BME, 0xF2, 0x01);                  /* humidity x1 */\n        write_reg(BME, 0xF4, 0x25);                           /* temperature x1, pressure x1, forced mode: one measurement */\n        uint8_t st = 8; for (int n = 0; n < 200 && (st & 8); n++) { delay_ms(2); read_regs(BME, 0xF3, &st, 1); }\n        uint8_t d[8]; read_regs(BME, 0xF7, d, bme ? 8 : 6);\n        int32_t T = comp_T((d[3] << 12) | (d[4] << 4) | (d[5] >> 4)); uint32_t P = comp_P((d[0] << 12) | (d[1] << 4) | (d[2] >> 4));\n        char line[24];\n        fmt(line, \"T:\", T, 2, \"C\"); oled_text(2, line); puts_(line); puts_(\"   \");\n        fmt(line, \"P:\", (int32_t)((P >> 8) / 10), 1, \"hPa\"); oled_text(4, line); puts_(line); puts_(\"   \");\n        if (bme) { fmt(line, \"H:\", (int32_t)((comp_H((d[6] << 8) | d[7]) * 10) >> 10), 1, \"%\"); oled_text(6, line); puts_(line); }\n        puts_(\"\\r\\n\"); delay_ms(1000);\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"oled1","type":"oled","x":300,"y":200,"attrs":{"color":"white","i2c-address":"0x3C","height":"64"}},{"id":"bme1","type":"bme280","x":560,"y":200,"attrs":{"temp":"23.5","pres":"1008.3","hum":"46"}}],"wires":[["oled1:GND","bluepill:GND.3","black"],["oled1:VCC","bluepill:3V3.2","red"],["oled1:SCL","bluepill:PB10","green"],["oled1:SDA","bluepill:PB11","blue"],["bme1:GND","bluepill:GND.3","black"],["bme1:VCC","bluepill:3V3.2","red"],["bme1:SCL","bluepill:PB10","green"],["bme1:SDA","bluepill:PB11","blue"]]}},{"id":"ds3231_lcd_clock","title":"DS3231 clock shown on an I2C LCD (needs 5 V)","src":"/* Real-time clock: a DS3231 module (I2C address 0x68) shown on a 16x2 LCD with an I2C backpack (PCF8574, address 0x27).\n   Both sit on I2C2 (SCL = PB10, SDA = PB11). The LCD needs 5 V, so both modules are powered from the 5 V pin.\n   The DS3231 starts from your computer's clock; set another start time in its inspector. */\n#include <stdint.h>\n#include \"stm32f1.h\"\n\nstatic volatile uint32_t ms; void SysTick_Handler(void) { ms++; }\nstatic void delay_ms(uint32_t d) { uint32_t t = ms + d; while ((int32_t)(ms - t) < 0) { } }\n\n/* ---- minimal I2C2 master driver (PB10 = SCL, PB11 = SDA). Every wait has a timeout, so a missing pull-up or a\n   wrong address is reported as an error code instead of hanging the program.  0 = ok, 1 = NACK, 2 = bus fault ---- */\n#define TIMEOUT 30000\nstatic int wait_flag(uint32_t f) {\n    for (int n = TIMEOUT; n; n--) { uint32_t s = I2C2->SR1; if (s & f) return 0; if (s & I2C_SR1_AF) return 1; if (s & (1u << 9)) return 2; }\n    return 2;\n}\nstatic void bus_reset(void) { I2C2->CR1 &= ~I2C_CR1_PE; I2C2->CR1 |= I2C_CR1_PE; }\nstatic void stop(void) { I2C2->CR1 |= I2C_CR1_STOP; for (int n = TIMEOUT; n && (I2C2->CR1 & I2C_CR1_STOP); n--); }\nstatic int fail(int r) { if (r == 1) { I2C2->SR1 &= ~I2C_SR1_AF; stop(); } else bus_reset(); return r; }\nstatic void i2c_init(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPBEN | RCC_APB2ENR_AFIOEN; RCC->APB1ENR |= RCC_APB1ENR_I2C2EN;\n    gpio_cfg(GPIOB, 10, GPIO_AF_OD_50MHZ); gpio_cfg(GPIOB, 11, GPIO_AF_OD_50MHZ);\n    I2C2->CR2 = 8; I2C2->CCR = 40; I2C2->TRISE = 9; I2C2->CR1 = I2C_CR1_PE;                 /* 100 kHz at 8 MHz */\n}\nstatic int i2c_write(uint8_t a7, const uint8_t *d, int n, int with_stop) {\n    int r; I2C2->CR1 |= I2C_CR1_START;\n    if ((r = wait_flag(I2C_SR1_SB))) return fail(r);\n    I2C2->DR = (uint8_t)(a7 << 1);\n    if ((r = wait_flag(I2C_SR1_ADDR))) return fail(r);\n    (void)I2C2->SR2;\n    for (int i = 0; i < n; i++) { if ((r = wait_flag(I2C_SR1_TXE))) return fail(r); I2C2->DR = d[i]; }\n    if (n && (r = wait_flag(I2C_SR1_BTF))) return fail(r);\n    if (with_stop) stop();\n    return 0;\n}\nstatic int i2c_read(uint8_t a7, uint8_t *d, int n) {          /* the three receive sequences of RM0008 */\n    int r; I2C2->CR1 |= I2C_CR1_ACK; if (n == 2) I2C2->CR1 |= I2C_CR1_POS;\n    I2C2->CR1 |= I2C_CR1_START;\n    if ((r = wait_flag(I2C_SR1_SB))) { I2C2->CR1 &= ~I2C_CR1_POS; return fail(r); }\n    I2C2->DR = (uint8_t)((a7 << 1) | 1);\n    if ((r = wait_flag(I2C_SR1_ADDR))) { I2C2->CR1 &= ~I2C_CR1_POS; return fail(r); }\n    if (n == 1) { I2C2->CR1 &= ~I2C_CR1_ACK; (void)I2C2->SR2; I2C2->CR1 |= I2C_CR1_STOP; if ((r = wait_flag(I2C_SR1_RXNE))) return fail(r); d[0] = (uint8_t)I2C2->DR; }\n    else if (n == 2) { (void)I2C2->SR2; I2C2->CR1 &= ~I2C_CR1_ACK; if ((r = wait_flag(I2C_SR1_BTF))) return fail(r); I2C2->CR1 |= I2C_CR1_STOP; d[0] = (uint8_t)I2C2->DR; d[1] = (uint8_t)I2C2->DR; }\n    else {\n        (void)I2C2->SR2;\n        while (n > 3) { if ((r = wait_flag(I2C_SR1_BTF))) return fail(r); *d++ = (uint8_t)I2C2->DR; n--; }\n        if ((r = wait_flag(I2C_SR1_BTF))) { return fail(r); }\n        I2C2->CR1 &= ~I2C_CR1_ACK; *d++ = (uint8_t)I2C2->DR; I2C2->CR1 |= I2C_CR1_STOP;\n        *d++ = (uint8_t)I2C2->DR;\n        if ((r = wait_flag(I2C_SR1_RXNE))) { return fail(r); }\n        *d++ = (uint8_t)I2C2->DR;\n    }\n    for (int k = TIMEOUT; k && (I2C2->CR1 & I2C_CR1_STOP); k--);\n    I2C2->CR1 &= ~I2C_CR1_POS; return 0;\n}\nstatic int read_regs(uint8_t a7, uint8_t reg, uint8_t *d, int n) {      /* write the register number, repeated START, read n bytes */\n    int r = i2c_write(a7, &reg, 1, 0); if (r) return r; return i2c_read(a7, d, n);\n}\n\n#define LCD 0x27\n#define RTC 0x68\nstatic void pcf(uint8_t v) { i2c_write(LCD, &v, 1, 1); }\nstatic void nib(uint8_t n, uint8_t rs) { uint8_t b = (uint8_t)((n << 4) | 0x08 | rs); pcf((uint8_t)(b | 4)); pcf(b); }   /* P3 = backlight, E pulse on P2 */\nstatic void lcd_byte(uint8_t v, uint8_t rs) { nib(v >> 4, rs); nib(v & 15, rs); }\nstatic void lcd_init(void) {\n    delay_ms(50); nib(3, 0); delay_ms(5); nib(3, 0); delay_ms(1); nib(3, 0); nib(2, 0);       /* HD44780: switch to 4-bit mode */\n    lcd_byte(0x28, 0); lcd_byte(0x0C, 0); lcd_byte(0x06, 0); lcd_byte(0x01, 0); delay_ms(3);\n}\nstatic void lcd_at(int row, int col) { lcd_byte((uint8_t)(0x80 | (row ? 0x40 : 0) | col), 0); }\nstatic void lcd_str(const char *s) { while (*s) { lcd_byte((uint8_t)*s++, 1); } }\nstatic void two(char *o, int v) { o[0] = (char)('0' + v / 10); o[1] = (char)('0' + v % 10); }\n\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN; SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7;\n    i2c_init(); lcd_init();\n    static const char *days[] = { \"???\", \"Sun\", \"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\" };\n    int last = -1;\n    for (;;) {\n        uint8_t t[7];\n        if (read_regs(RTC, 0x00, t, 7)) { lcd_at(0, 0); lcd_str(\"RTC not found   \"); delay_ms(500); continue; }\n        int sec = (t[0] >> 4) * 10 + (t[0] & 15);\n        if (sec != last) {\n            last = sec;\n            char a[17] = \"    00:00:00    \", b[17] = \"2000-00-00 Sun  \";\n            two(a + 4, (t[2] >> 4 & 3) * 10 + (t[2] & 15)); two(a + 7, (t[1] >> 4) * 10 + (t[1] & 15)); two(a + 10, sec);\n            two(b + 2, (t[6] >> 4) * 10 + (t[6] & 15)); two(b + 5, (t[5] >> 4 & 1) * 10 + (t[5] & 15)); two(b + 8, (t[4] >> 4) * 10 + (t[4] & 15));\n            const char *d = days[t[3] & 7]; b[11] = d[0]; b[12] = d[1]; b[13] = d[2];\n            lcd_at(0, 0); lcd_str(a); lcd_at(1, 0); lcd_str(b);\n        }\n        delay_ms(100);\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"rtc1","type":"ds3231","x":540,"y":50,"attrs":{"temp":"25","start":"","eeprom":"yes","eeaddr":"0x57"}},{"id":"lcd1","type":"lcdi2c","x":250,"y":340,"attrs":{"i2c-address":"0x27"}}],"wires":[["rtc1:GND","bluepill:GND.3","black"],["rtc1:VCC","bluepill:5V","red"],["rtc1:SCL","bluepill:PB10","green"],["rtc1:SDA","bluepill:PB11","blue"],["lcd1:GND","bluepill:GND.3","black"],["lcd1:VCC","bluepill:5V","red"],["lcd1:SCL","bluepill:PB10","green"],["lcd1:SDA","bluepill:PB11","blue"]]}},{"id":"eeprom_counter","title":"AT24C32 EEPROM boot counter (survives Stop/Run, needs pull-ups)","src":"/* Non-volatile boot counter in an AT24C32 EEPROM module (I2C address 0x50, 2-byte memory addresses, 32-byte pages).\n   Press Stop and Run again: the counter keeps counting, because the EEPROM keeps its contents (like the real chip).\n   Writing takes about 5 ms; during that time the chip does not acknowledge its address, which is how \"ACK polling\"\n   knows when the write has finished. The bare EEPROM module has NO pull-up resistors: the two 4.7k resistors\n   on SCL and SDA in the circuit are required, just like on a real breadboard. */\n#include <stdint.h>\n#include \"stm32f1.h\"\n\nstatic volatile uint32_t ms; void SysTick_Handler(void) { ms++; }\nstatic void uart_init(void) { RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_USART1EN; gpio_cfg(GPIOA, 9, GPIO_AF_PP_2MHZ); USART1->BRR = 8000000 / 115200; USART1->CR1 = (1u << 13) | (1u << 3); SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7; }\nstatic void putc_(char c) { while (!(USART1->SR & 0x80)); USART1->DR = (uint32_t)c; }\nstatic void puts_(const char *s) { while (*s) putc_(*s++); }\n\n/* ---- minimal I2C2 master driver (PB10 = SCL, PB11 = SDA). Every wait has a timeout, so a missing pull-up or a\n   wrong address is reported as an error code instead of hanging the program.  0 = ok, 1 = NACK, 2 = bus fault ---- */\n#define TIMEOUT 30000\nstatic int wait_flag(uint32_t f) {\n    for (int n = TIMEOUT; n; n--) { uint32_t s = I2C2->SR1; if (s & f) return 0; if (s & I2C_SR1_AF) return 1; if (s & (1u << 9)) return 2; }\n    return 2;\n}\nstatic void bus_reset(void) { I2C2->CR1 &= ~I2C_CR1_PE; I2C2->CR1 |= I2C_CR1_PE; }\nstatic void stop(void) { I2C2->CR1 |= I2C_CR1_STOP; for (int n = TIMEOUT; n && (I2C2->CR1 & I2C_CR1_STOP); n--); }\nstatic int fail(int r) { if (r == 1) { I2C2->SR1 &= ~I2C_SR1_AF; stop(); } else bus_reset(); return r; }\nstatic void i2c_init(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPBEN | RCC_APB2ENR_AFIOEN; RCC->APB1ENR |= RCC_APB1ENR_I2C2EN;\n    gpio_cfg(GPIOB, 10, GPIO_AF_OD_50MHZ); gpio_cfg(GPIOB, 11, GPIO_AF_OD_50MHZ);\n    I2C2->CR2 = 8; I2C2->CCR = 40; I2C2->TRISE = 9; I2C2->CR1 = I2C_CR1_PE;                 /* 100 kHz at 8 MHz */\n}\nstatic int i2c_write(uint8_t a7, const uint8_t *d, int n, int with_stop) {\n    int r; I2C2->CR1 |= I2C_CR1_START;\n    if ((r = wait_flag(I2C_SR1_SB))) return fail(r);\n    I2C2->DR = (uint8_t)(a7 << 1);\n    if ((r = wait_flag(I2C_SR1_ADDR))) return fail(r);\n    (void)I2C2->SR2;\n    for (int i = 0; i < n; i++) { if ((r = wait_flag(I2C_SR1_TXE))) return fail(r); I2C2->DR = d[i]; }\n    if (n && (r = wait_flag(I2C_SR1_BTF))) return fail(r);\n    if (with_stop) stop();\n    return 0;\n}\nstatic int i2c_read(uint8_t a7, uint8_t *d, int n) {          /* the three receive sequences of RM0008 */\n    int r; I2C2->CR1 |= I2C_CR1_ACK; if (n == 2) I2C2->CR1 |= I2C_CR1_POS;\n    I2C2->CR1 |= I2C_CR1_START;\n    if ((r = wait_flag(I2C_SR1_SB))) { I2C2->CR1 &= ~I2C_CR1_POS; return fail(r); }\n    I2C2->DR = (uint8_t)((a7 << 1) | 1);\n    if ((r = wait_flag(I2C_SR1_ADDR))) { I2C2->CR1 &= ~I2C_CR1_POS; return fail(r); }\n    if (n == 1) { I2C2->CR1 &= ~I2C_CR1_ACK; (void)I2C2->SR2; I2C2->CR1 |= I2C_CR1_STOP; if ((r = wait_flag(I2C_SR1_RXNE))) return fail(r); d[0] = (uint8_t)I2C2->DR; }\n    else if (n == 2) { (void)I2C2->SR2; I2C2->CR1 &= ~I2C_CR1_ACK; if ((r = wait_flag(I2C_SR1_BTF))) return fail(r); I2C2->CR1 |= I2C_CR1_STOP; d[0] = (uint8_t)I2C2->DR; d[1] = (uint8_t)I2C2->DR; }\n    else {\n        (void)I2C2->SR2;\n        while (n > 3) { if ((r = wait_flag(I2C_SR1_BTF))) return fail(r); *d++ = (uint8_t)I2C2->DR; n--; }\n        if ((r = wait_flag(I2C_SR1_BTF))) { return fail(r); }\n        I2C2->CR1 &= ~I2C_CR1_ACK; *d++ = (uint8_t)I2C2->DR; I2C2->CR1 |= I2C_CR1_STOP;\n        *d++ = (uint8_t)I2C2->DR;\n        if ((r = wait_flag(I2C_SR1_RXNE))) { return fail(r); }\n        *d++ = (uint8_t)I2C2->DR;\n    }\n    for (int k = TIMEOUT; k && (I2C2->CR1 & I2C_CR1_STOP); k--);\n    I2C2->CR1 &= ~I2C_CR1_POS; return 0;\n}\n\n#define EE 0x50\nstatic void put_dec(uint32_t v) { char b[11]; int k = 0; do { b[k++] = (char)('0' + v % 10); v /= 10; } while (v); while (k) { putc_(b[--k]); } }\nint main(void) {\n    uart_init(); i2c_init();\n    puts_(\"AT24C32 boot counter\\r\\n\");\n    uint8_t ptr[2] = { 0x00, 0x00 }, rec[5] = { 0 };\n    int r = i2c_write(EE, ptr, 2, 0);                         /* set the address pointer to 0x0000 ... */\n    if (!r) { r = i2c_read(EE, rec, 5); }                     /* ... then read 5 bytes (repeated START) */\n    if (r) { puts_(\"EEPROM not answering (pull-up resistors? address pins?)\\r\\n\"); for (;;) { } }\n    uint32_t count = 0;\n    if (rec[0] == 0xA5) { count = (uint32_t)rec[1] | (uint32_t)rec[2] << 8 | (uint32_t)rec[3] << 16 | (uint32_t)rec[4] << 24; }\n    else { puts_(\"blank EEPROM: starting at 0\\r\\n\"); }\n    count++;\n    uint8_t w[7] = { 0x00, 0x00, 0xA5, (uint8_t)count, (uint8_t)(count >> 8), (uint8_t)(count >> 16), (uint8_t)(count >> 24) };\n    r = i2c_write(EE, w, 7, 1);                               /* one page write: 5 data bytes */\n    uint32_t t0 = ms; int polls = 0;\n    while (i2c_write(EE, 0, 0, 1) != 0 && ms - t0 < 50) { polls++; }   /* ACK polling: NACK while the internal write cycle runs */\n    puts_(\"Boot count: \"); put_dec(count); puts_(r ? \"  (write failed)\" : \"\"); puts_(\"\\r\\n\");\n    puts_(\"write cycle took \"); put_dec(ms - t0); puts_(\" ms, \"); put_dec((uint32_t)polls); puts_(\" NACKs while polling\\r\\n\");\n    puts_(\"Press Stop, then Run again: the counter survives.\\r\\n\");\n    for (;;) { }\n}\n","b64":"","circuit":{"parts":[{"id":"ee1","type":"at24","x":340,"y":240,"attrs":{"size":"24C32","wp":"0"}},{"id":"r1","type":"res","x":560,"y":80,"attrs":{"value":"4700"}},{"id":"r2","type":"res","x":560,"y":120,"attrs":{"value":"4700"}}],"wires":[["ee1:GND","bluepill:GND.3","black"],["ee1:VCC","bluepill:3V3.2","red"],["ee1:SCL","bluepill:PB10","green"],["ee1:SDA","bluepill:PB11","blue"],["r1:1","bluepill:PB10","green"],["r1:2","bluepill:3V3.2","red"],["r2:1","bluepill:PB11","blue"],["r2:2","bluepill:3V3.2","red"]]}},{"id":"knight_rider","title":"LED bar graph: Knight Rider","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n/* LED bar graph \"Knight Rider\": A1..A10 = PA0..PA7, PB0, PB1. One lit LED sweeps back and forth with a fading tail. */\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\nstatic void show(uint32_t mask) { GPIOA->ODR = (GPIOA->ODR & ~0xFFu) | (mask & 0xFFu); GPIOB->ODR = (GPIOB->ODR & ~3u) | ((mask >> 8) & 3u); }\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_IOPBEN;\n    for (int i = 0; i < 8; i++) gpio_cfg(GPIOA, i, GPIO_OUT_PP_2MHZ);\n    gpio_cfg(GPIOB, 0, GPIO_OUT_PP_2MHZ); gpio_cfg(GPIOB, 1, GPIO_OUT_PP_2MHZ);\n    SysTick->LOAD = 8000 - 1; SysTick->CTRL = 7;\n    int pos = 0, dir = 1; uint32_t last = 0;\n    for (;;) {\n        if (ms - last >= 80) { last = ms; show((1u << pos) | (1u << (pos - dir >= 0 && pos - dir < 10 ? pos - dir : pos)));\n            pos += dir; if (pos >= 9 || pos <= 0) dir = -dir; }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"bar1","type":"bar","x":300,"y":200,"attrs":{"color":"green"}}],"wires":[["bar1:A1","bluepill:PA0","green"],["bar1:A2","bluepill:PA1","green"],["bar1:A3","bluepill:PA2","green"],["bar1:A4","bluepill:PA3","green"],["bar1:A5","bluepill:PA4","green"],["bar1:A6","bluepill:PA5","green"],["bar1:A7","bluepill:PA6","green"],["bar1:A8","bluepill:PA7","green"],["bar1:A9","bluepill:PB0","green"],["bar1:A10","bluepill:PB1","green"],["bar1:C1","bluepill:GND.2","black"],["bar1:C2","bluepill:GND.2","black"],["bar1:C3","bluepill:GND.2","black"],["bar1:C4","bluepill:GND.2","black"],["bar1:C5","bluepill:GND.2","black"],["bar1:C6","bluepill:GND.2","black"],["bar1:C7","bluepill:GND.2","black"],["bar1:C8","bluepill:GND.2","black"],["bar1:C9","bluepill:GND.2","black"],["bar1:C10","bluepill:GND.2","black"]]}},{"id":"switch_led","title":"Slide switch controls an LED","src":"#include <stdint.h>\n#include \"stm32f1.h\"\n/* Slide switch on PA0 (pin 1 = 3V3, pin 3 = GND) controls the LED on PA5 and reports on USART1. Click the switch while running! */\nstatic void tx(char c) { while (!(USART1->SR & 0x80)); USART1->DR = c; }\nstatic void say(const char *s) { while (*s) tx(*s++); }\nint main(void) {\n    RCC->APB2ENR |= RCC_APB2ENR_IOPAEN | RCC_APB2ENR_USART1EN;\n    gpio_cfg(GPIOA, 5, GPIO_OUT_PP_2MHZ); gpio_cfg(GPIOA, 0, GPIO_IN_FLOATING); gpio_cfg(GPIOA, 9, GPIO_AF_PP_2MHZ);\n    USART1->BRR = 69; USART1->CR1 = (1u << 13) | (1u << 3);\n    int last = -1;\n    for (;;) {\n        int on = (GPIOA->IDR & 1u) ? 1 : 0;\n        if (on != last) { last = on; GPIOA->BSRR = on ? (1u << 5) : (1u << 21); say(on ? \"switch ON\\r\\n\" : \"switch OFF\\r\\n\"); }\n        for (volatile uint32_t i = 0; i < 300; i++);\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"sw1","type":"sw","x":400,"y":200,"pos":0,"attrs":{}},{"id":"led1","type":"led","x":400,"y":340,"attrs":{"color":"red"}}],"wires":[["sw1:1","bluepill:3V3.2","red"],["sw1:3","bluepill:GND.2","black"],["sw1:2","bluepill:PA0","green"],["led1:A","bluepill:PA5","green"],["led1:C","bluepill:GND.3","black"]]}},{"id":"demo","title":"Register-level: blink + button + UART","src":"#define RCC_APB2ENR (*(volatile unsigned *)0x40021018)\n#define GPIOA_CRL   (*(volatile unsigned *)0x40010800)\n#define GPIOA_CRH   (*(volatile unsigned *)0x40010804)\n#define GPIOA_IDR   (*(volatile unsigned *)0x40010808)\n#define GPIOA_ODR   (*(volatile unsigned *)0x4001080C)\n#define GPIOA_BSRR  (*(volatile unsigned *)0x40010810)\n#define GPIOC_CRH   (*(volatile unsigned *)0x40011004)\n#define GPIOC_ODR   (*(volatile unsigned *)0x4001100C)\n#define USART1_SR   (*(volatile unsigned *)0x40013800)\n#define USART1_DR   (*(volatile unsigned *)0x40013804)\n#define USART1_BRR  (*(volatile unsigned *)0x40013808)\n#define USART1_CR1  (*(volatile unsigned *)0x4001380C)\n#define STK_CTRL    (*(volatile unsigned *)0xE000E010)\n#define STK_LOAD    (*(volatile unsigned *)0xE000E014)\n\nstatic volatile unsigned ms;\nvoid SysTick_Handler(void) { ms++; }\n\nstatic void tx(char c) { while (!(USART1_SR & 0x80)); USART1_DR = c; }\nstatic void say(const char *s) { while (*s) tx(*s++); }\n\nint main(void) {\n    RCC_APB2ENR |= (1u << 2) | (1u << 4) | (1u << 14);   /* GPIOA, GPIOC, USART1 */\n    GPIOA_CRL = (GPIOA_CRL & ~0x00F0000Fu) | 0x8u | (0x2u << 20); /* PA0 in (pull), PA5 out */\n    GPIOA_CRH = (GPIOA_CRH & ~(0xFu << 4)) | (0xAu << 4);        /* PA9 = USART1 TX       */\n    GPIOA_ODR |= 1u;                                             /* PA0 pull-up           */\n    GPIOC_CRH = (GPIOC_CRH & ~(0xFu << 20)) | (0x2u << 20);      /* PC13 out              */\n    USART1_BRR = 69;                                             /* 8 MHz / 115200        */\n    USART1_CR1 = (1u << 13) | (1u << 3);                         /* UE | TE               */\n    STK_LOAD = 8000 - 1;  STK_CTRL = 7;                          /* 1 ms SysTick          */\n\n    say(\"PinForge STM32F103 demo\\r\\n\");\n    unsigned last = 0, prev = 1;\n    while (1) {\n        if (ms - last >= 500) { last = ms; GPIOC_ODR ^= 1u << 13; }   /* blink PC13 */\n        unsigned b = GPIOA_IDR & 1u;\n        if (b != prev) { prev = b; say(b ? \"button released\\r\\n\" : \"button pressed\\r\\n\"); }\n        GPIOA_BSRR = b ? (1u << 21) : (1u << 5);                       /* button -> LED PA5 */\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"btn1","type":"btn","x":360,"y":100,"attrs":{"color":"green"}},{"id":"led1","type":"led","x":360,"y":240,"attrs":{"color":"red"}}],"wires":[["led1:A","bluepill:PA5","green"],["led1:C","bluepill:GND.3","black"],["btn1:1.l","bluepill:PA0","blue"],["btn1:2.l","bluepill:GND.2","black"]]}},{"id":"blink","title":"Blink PC13 (register level)","src":"#define RCC_APB2ENR (*(volatile unsigned *)0x40021018)\n#define GPIOC_CRH   (*(volatile unsigned *)0x40011004)\n#define GPIOC_ODR   (*(volatile unsigned *)0x4001100C)\n\nint main(void) {\n    RCC_APB2ENR |= (1u << 4);            /* enable GPIOC clock   */\n    GPIOC_CRH &= ~(0xFu << 20);          /* PC13: clear CNF/MODE */\n    GPIOC_CRH |=  (0x2u << 20);          /* output, 2 MHz        */\n    while (1) {\n        GPIOC_ODR ^= (1u << 13);         /* toggle the LED       */\n        for (volatile int i = 0; i < 333000; i++);\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"btn1","type":"btn","x":360,"y":100,"attrs":{"color":"green"}},{"id":"led1","type":"led","x":360,"y":240,"attrs":{"color":"red"}}],"wires":[["led1:A","bluepill:PA5","green"],["led1:C","bluepill:GND.3","black"],["btn1:1.l","bluepill:PA0","blue"],["btn1:2.l","bluepill:GND.2","black"]]}},{"id":"button","title":"Button to LED (polling)","src":"#define RCC_APB2ENR (*(volatile unsigned *)0x40021018)\n#define GPIOA_CRL   (*(volatile unsigned *)0x40010800)\n#define GPIOA_IDR   (*(volatile unsigned *)0x40010808)\n#define GPIOA_ODR   (*(volatile unsigned *)0x4001080C)\n#define GPIOA_BSRR  (*(volatile unsigned *)0x40010810)\n\nint main(void) {\n    RCC_APB2ENR |= (1u << 2);                  /* GPIOA clock          */\n    GPIOA_CRL = (GPIOA_CRL & ~0x00F0000Fu)\n              | (0x8u << 0)                    /* PA0: input pull      */\n              | (0x2u << 20);                  /* PA5: output 2 MHz    */\n    GPIOA_ODR |= 1u;                           /* PA0 pull-up          */\n    while (1) {\n        if (GPIOA_IDR & 1u) GPIOA_BSRR = 1u << (5 + 16);   /* released: LED off */\n        else                GPIOA_BSRR = 1u << 5;          /* pressed: LED on   */\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"btn1","type":"btn","x":360,"y":100,"attrs":{"color":"green"}},{"id":"led1","type":"led","x":360,"y":240,"attrs":{"color":"red"}}],"wires":[["led1:A","bluepill:PA5","green"],["led1:C","bluepill:GND.3","black"],["btn1:1.l","bluepill:PA0","blue"],["btn1:2.l","bluepill:GND.2","black"]]}},{"id":"exti","title":"Button interrupt (EXTI0)","src":"#define RCC_APB2ENR (*(volatile unsigned *)0x40021018)\n#define AFIO_EXTICR1 (*(volatile unsigned *)0x40010008)\n#define EXTI_IMR    (*(volatile unsigned *)0x40010400)\n#define EXTI_FTSR   (*(volatile unsigned *)0x4001040C)\n#define EXTI_PR     (*(volatile unsigned *)0x40010414)\n#define NVIC_ISER0  (*(volatile unsigned *)0xE000E100)\n#define GPIOA_CRL   (*(volatile unsigned *)0x40010800)\n#define GPIOA_ODR   (*(volatile unsigned *)0x4001080C)\n\nvoid EXTI0_IRQHandler(void) {\n    EXTI_PR = 1u;                       /* clear the pending flag    */\n    GPIOA_ODR ^= (1u << 5);             /* toggle the LED on PA5     */\n}\n\nint main(void) {\n    RCC_APB2ENR |= (1u << 0) | (1u << 2);                 /* AFIO + GPIOA */\n    GPIOA_CRL = (GPIOA_CRL & ~0x00F0000Fu) | 0x8u | (0x2u << 20);\n    GPIOA_ODR |= 1u;                                      /* PA0 pull-up  */\n    AFIO_EXTICR1 = 0;                                     /* EXTI0 <- PA0 */\n    EXTI_FTSR |= 1u;                                      /* falling edge */\n    EXTI_IMR  |= 1u;\n    NVIC_ISER0 = 1u << 6;                                 /* enable EXTI0 IRQ */\n    for (;;) __asm volatile (\"wfi\");\n}\n","b64":"","circuit":{"parts":[{"id":"btn1","type":"btn","x":360,"y":100,"attrs":{"color":"green"}},{"id":"led1","type":"led","x":360,"y":240,"attrs":{"color":"red"}}],"wires":[["led1:A","bluepill:PA5","green"],["led1:C","bluepill:GND.3","black"],["btn1:1.l","bluepill:PA0","blue"],["btn1:2.l","bluepill:GND.2","black"]]}},{"id":"systick","title":"SysTick millisecond timer","src":"#define RCC_APB2ENR (*(volatile unsigned *)0x40021018)\n#define GPIOC_CRH   (*(volatile unsigned *)0x40011004)\n#define GPIOC_ODR   (*(volatile unsigned *)0x4001100C)\n#define STK_CTRL    (*(volatile unsigned *)0xE000E010)\n#define STK_LOAD    (*(volatile unsigned *)0xE000E014)\n\nstatic volatile unsigned ms;\n\nvoid SysTick_Handler(void) { ms++; }       /* fires every millisecond */\n\nstatic void delay_ms(unsigned t) { unsigned s = ms; while (ms - s < t); }\n\nint main(void) {\n    RCC_APB2ENR |= (1u << 4);\n    GPIOC_CRH = (GPIOC_CRH & ~(0xFu << 20)) | (0x2u << 20);\n    STK_LOAD = 8000 - 1;                    /* 8 MHz / 1 kHz */\n    STK_CTRL = 7;                           /* enable, interrupt, HCLK */\n    while (1) {\n        GPIOC_ODR ^= (1u << 13);\n        delay_ms(250);\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"btn1","type":"btn","x":360,"y":100,"attrs":{"color":"green"}},{"id":"led1","type":"led","x":360,"y":240,"attrs":{"color":"red"}}],"wires":[["led1:A","bluepill:PA5","green"],["led1:C","bluepill:GND.3","black"],["btn1:1.l","bluepill:PA0","blue"],["btn1:2.l","bluepill:GND.2","black"]]}},{"id":"uart","title":"UART hello (USART1)","src":"#define RCC_APB2ENR (*(volatile unsigned *)0x40021018)\n#define USART1_SR   (*(volatile unsigned *)0x40013800)\n#define USART1_DR   (*(volatile unsigned *)0x40013804)\n#define USART1_BRR  (*(volatile unsigned *)0x40013808)\n#define USART1_CR1  (*(volatile unsigned *)0x4001380C)\n\nstatic void putc_(char c) { while (!(USART1_SR & 0x80)); USART1_DR = c; }\nstatic void puts_(const char *s) { while (*s) putc_(*s++); }\nstatic void putu(unsigned v) {\n    char b[11]; int i = 0;\n    do { b[i++] = '0' + v % 10; v /= 10; } while (v);\n    while (i) putc_(b[--i]);\n}\n\nint main(void) {\n    RCC_APB2ENR |= (1u << 14);              /* USART1 clock */\n    USART1_BRR = 8000000 / 115200;\n    USART1_CR1 = (1u << 13) | (1u << 3);    /* UE | TE */\n    puts_(\"Hello from STM32F103!\\r\\n\");\n    for (unsigned n = 1;; n++) {\n        puts_(\"count = \"); putu(n * n); puts_(\"\\r\\n\");\n        for (volatile unsigned i = 0; i < 200000; i++);\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"btn1","type":"btn","x":360,"y":100,"attrs":{"color":"green"}},{"id":"led1","type":"led","x":360,"y":240,"attrs":{"color":"red"}}],"wires":[["led1:A","bluepill:PA5","green"],["led1:C","bluepill:GND.3","black"],["btn1:1.l","bluepill:PA0","blue"],["btn1:2.l","bluepill:GND.2","black"]]}},{"id":"adc","title":"ADC + potentiometer (PA1)","src":"#define RCC_APB2ENR (*(volatile unsigned *)0x40021018)\n#define GPIOA_CRL   (*(volatile unsigned *)0x40010800)\n#define GPIOA_BSRR  (*(volatile unsigned *)0x40010810)\n#define ADC1_SR     (*(volatile unsigned *)0x40012400)\n#define ADC1_CR2    (*(volatile unsigned *)0x40012408)\n#define ADC1_SQR3   (*(volatile unsigned *)0x40012434)\n#define ADC1_DR     (*(volatile unsigned *)0x4001244C)\n#define USART1_SR   (*(volatile unsigned *)0x40013800)\n#define USART1_DR   (*(volatile unsigned *)0x40013804)\n#define USART1_BRR  (*(volatile unsigned *)0x40013808)\n#define USART1_CR1  (*(volatile unsigned *)0x4001380C)\n\nstatic void tx(char c) { while (!(USART1_SR & 0x80)); USART1_DR = c; }\nstatic void say(const char *s) { while (*s) tx(*s++); }\nstatic void num(unsigned v) { char b[6]; int i = 0; do { b[i++] = '0' + v % 10; v /= 10; } while (v); while (i) tx(b[--i]); }\n\nint main(void) {\n    RCC_APB2ENR |= (1u << 2) | (1u << 9) | (1u << 14);          /* GPIOA, ADC1, USART1 */\n    GPIOA_CRL = (GPIOA_CRL & ~0x00F000F0u) | (0x2u << 20);          /* PA1 analog, PA5 output */\n    USART1_BRR = 69; USART1_CR1 = (1u << 13) | (1u << 3);\n    ADC1_CR2 = 1; ADC1_CR2 |= 4; while (ADC1_CR2 & 4);          /* power up + calibrate */\n    ADC1_SQR3 = 1;                                              /* channel 1 = PA1      */\n    say(\"ADC demo: wire a potentiometer SIG pin to PA1\\r\\n\");\n    for (;;) {\n        ADC1_CR2 |= (1u << 22);                                 /* start conversion */\n        while (!(ADC1_SR & 2));\n        unsigned v = ADC1_DR;\n        say(\"ADC1 = \"); num(v); say(\"\\r\\n\");\n        GPIOA_BSRR = v > 2048 ? (1u << 5) : (1u << 21);         /* LED on above half scale */\n        for (volatile unsigned i = 0; i < 120000; i++);\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"btn1","type":"btn","x":360,"y":100,"attrs":{"color":"green"}},{"id":"led1","type":"led","x":360,"y":240,"attrs":{"color":"red"}},{"id":"pot1","type":"pot","x":300,"y":380,"attrs":{}}],"wires":[["led1:A","bluepill:PA5","green"],["led1:C","bluepill:GND.3","black"],["btn1:1.l","bluepill:PA0","blue"],["btn1:2.l","bluepill:GND.2","black"],["pot1:SIG","bluepill:PA1","orange"],["pot1:VCC","bluepill:3V3.2","red"],["pot1:GND","bluepill:GND.3","black"]]}},{"id":"lpc_start","title":"LPC1768 start here: blink + button + UART0 (lpc17xx.h)","src":"#include <stdint.h>\n#include \"lpc17xx.h\"\n\n/* LED on P2.0, push button on P2.1 (to GND, internal pull-up), serial console on UART0 (P0.2 / P0.3). CCLK = 4 MHz from the internal RC. */\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\n\nstatic void uart0_init(void) {\n    LPC_PINCON->PINSEL0 |= (1u << 4) | (1u << 6);       /* P0.2 = TXD0, P0.3 = RXD0 */\n    LPC_UART0->LCR = LCR_DLAB | 3;                      /* 8N1, open the divisor latch */\n    LPC_UART0->DLL = 6; LPC_UART0->DLM = 0;             /* PCLK = CCLK / 4 = 1 MHz: 1e6 / (16 * 6 * (1 + 1/12)) = 9615 baud */\n    LPC_UART0->FDR = (12u << 4) | 1;\n    LPC_UART0->LCR = 3;\n    LPC_UART0->FCR = 7;                                 /* enable and clear the FIFOs */\n}\nstatic void putc_(char c) { while (!(LPC_UART0->LSR & LSR_THRE)); LPC_UART0->THR = c; }\nstatic void puts_(const char *s) { while (*s) putc_(*s++); }\nstatic void putu(uint32_t v) { char b[11]; int n = 0; do { b[n++] = '0' + v % 10; v /= 10; } while (v); while (n) putc_(b[--n]); }\n\nint main(void) {\n    LPC_GPIO2->FIODIR |= 1u << 0;                       /* P2.0 output */\n    SysTick->LOAD = 4000 - 1;                           /* 1 ms at 4 MHz */\n    SysTick->CTRL = 7;                                  /* CCLK, interrupt, enable */\n    uart0_init();\n    puts_(\"PinForge LPC1768: blink + button + UART0\\r\\n\");\n    uint32_t next = 500, last = 0, presses = 0;\n    int led = 0, prev = 1;\n    for (;;) {\n        if (ms >= next) {\n            next += 500; led = !led;\n            if (led) LPC_GPIO2->FIOSET = 1u << 0; else LPC_GPIO2->FIOCLR = 1u << 0;\n        }\n        int now = (LPC_GPIO2->FIOPIN >> 1) & 1;         /* P2.1 */\n        if (!now && prev) { presses++; puts_(\"button pressed, count = \"); putu(presses); puts_(\"\\r\\n\"); }\n        prev = now;\n        if (ms - last >= 2000) { last = ms; puts_(\"uptime \"); putu(ms / 1000); puts_(\" s\\r\\n\"); }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"led1","type":"led","x":140,"y":380,"attrs":{"color":"red"}},{"id":"btn1","type":"btn","x":300,"y":380,"attrs":{"color":"green"}}],"wires":[["led1:A","lpc1768:P2.0","green"],["led1:C","lpc1768:GND.3","black"],["btn1:1.l","lpc1768:P2.1","blue"],["btn1:2.l","lpc1768:GND.3","black"]]},"board":"lpc1768"},{"id":"lpc_irq","title":"LPC1768 interrupts: Timer0 + GPIO interrupt + UART0","src":"#include <stdint.h>\n#include \"lpc17xx.h\"\n\n/* Interrupts: Timer0 match toggles the LED on P2.0 every 500 ms; a falling edge on P2.1 raises a GPIO interrupt (EINT3 vector);\n   the main loop reports both over UART0. CCLK = 4 MHz, Timer0 runs from PCLK = 1 MHz. */\nstatic volatile uint32_t ticks, presses;\nstatic volatile int led;\n\nvoid TIMER0_IRQHandler(void) {\n    LPC_TIM0->IR = 1;                                   /* clear the MR0 flag */\n    ticks++; led = !led;\n    if (led) LPC_GPIO2->FIOSET = 1u << 0; else LPC_GPIO2->FIOCLR = 1u << 0;\n}\nvoid EINT3_IRQHandler(void) {\n    if (LPC_GPIOINT->IO2IntStatF & (1u << 1)) { LPC_GPIOINT->IO2IntClr = 1u << 1; presses++; }\n}\nstatic void putc_(char c) { while (!(LPC_UART0->LSR & LSR_THRE)); LPC_UART0->THR = c; }\nstatic void puts_(const char *s) { while (*s) putc_(*s++); }\nstatic void putu(uint32_t v) { char b[11]; int n = 0; do { b[n++] = '0' + v % 10; v /= 10; } while (v); while (n) putc_(b[--n]); }\n\nint main(void) {\n    LPC_PINCON->PINSEL0 |= (1u << 4) | (1u << 6);\n    LPC_UART0->LCR = LCR_DLAB | 3; LPC_UART0->DLL = 6; LPC_UART0->DLM = 0; LPC_UART0->FDR = (12u << 4) | 1; LPC_UART0->LCR = 3; LPC_UART0->FCR = 7;\n    LPC_GPIO2->FIODIR |= 1u << 0;\n    LPC_TIM0->PR = 999;                                 /* 1 MHz / 1000 = 1 kHz timer tick */\n    LPC_TIM0->MR0 = 499;                                /* 500 ticks */\n    LPC_TIM0->MCR = 3;                                  /* interrupt and reset on MR0 */\n    LPC_TIM0->TCR = 1;\n    NVIC_EnableIRQ(TIMER0_IRQn);\n    LPC_GPIOINT->IO2IntEnF = 1u << 1;                   /* falling edge on P2.1 */\n    NVIC_EnableIRQ(EINT3_IRQn);\n    puts_(\"Timer0 + GPIO interrupts\\r\\n\");\n    uint32_t seenT = 0, seenP = 0;\n    for (;;) {\n        if (ticks != seenT) { seenT = ticks; puts_(\"Timer0 tick \"); putu(seenT); puts_(\"\\r\\n\"); }\n        if (presses != seenP) { seenP = presses; puts_(\"button interrupt, count = \"); putu(seenP); puts_(\"\\r\\n\"); }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"led1","type":"led","x":140,"y":380,"attrs":{"color":"red"}},{"id":"btn1","type":"btn","x":300,"y":380,"attrs":{"color":"green"}}],"wires":[["led1:A","lpc1768:P2.0","green"],["led1:C","lpc1768:GND.3","black"],["btn1:1.l","lpc1768:P2.1","blue"],["btn1:2.l","lpc1768:GND.3","black"]]},"board":"lpc1768"},{"id":"lpc_pll100","title":"LPC1768 PLL0: run at 100 MHz, SysTick blink, UART0 115200","src":"#include <stdint.h>\n#include \"lpc17xx.h\"\n\n/* Clock the chip at 100 MHz: 12 MHz crystal x 50 / 3 x 2 = 400 MHz PLL0 output, CCLK = 400 / 4 = 100 MHz, PCLK = 25 MHz.\n   Flash timing has to be raised first (FLASHTIM = 4), then PLL0 is enabled, locked and connected, each change needs the AA / 55 feed. */\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\nstatic void feed(void) { LPC_SC->PLL0FEED = 0xAA; LPC_SC->PLL0FEED = 0x55; }\n\nstatic void clock_100mhz(void) {\n    LPC_SC->FLASHCFG = (4u << 12) | 0x3A;\n    LPC_SC->SCS = SCS_OSCEN;  while (!(LPC_SC->SCS & SCS_OSCSTAT));\n    LPC_SC->CLKSRCSEL = 1;                              /* main oscillator */\n    LPC_SC->PLL0CFG = 49u | (2u << 16);                 /* M = 50, N = 3 */\n    feed();\n    LPC_SC->PLL0CON = 1; feed();\n    LPC_SC->CCLKCFG = 3;\n    while (!(LPC_SC->PLL0STAT & PLL0STAT_PLOCK));\n    LPC_SC->PLL0CON = 3; feed();                        /* connect */\n}\nstatic void putc_(char c) { while (!(LPC_UART0->LSR & LSR_THRE)); LPC_UART0->THR = c; }\nstatic void puts_(const char *s) { while (*s) putc_(*s++); }\nstatic void putu(uint32_t v) { char b[11]; int n = 0; do { b[n++] = '0' + v % 10; v /= 10; } while (v); while (n) putc_(b[--n]); }\n\nint main(void) {\n    clock_100mhz();\n    LPC_PINCON->PINSEL0 |= (1u << 4) | (1u << 6);\n    LPC_UART0->LCR = LCR_DLAB | 3;                      /* PCLK = 25 MHz: 25e6 / (16 * 12 * (1 + 2/15)) = 114889 baud (115200 -0.3 %) */\n    LPC_UART0->DLL = 12; LPC_UART0->DLM = 0; LPC_UART0->FDR = (15u << 4) | 2;\n    LPC_UART0->LCR = 3; LPC_UART0->FCR = 7;\n    LPC_GPIO2->FIODIR |= 1u << 0;\n    SysTick->LOAD = 100000 - 1;                         /* 1 ms at 100 MHz */\n    SysTick->CTRL = 7;\n    puts_(\"CCLK = 100 MHz (PLL0 locked and connected), UART0 at 115200 baud\\r\\n\");\n    uint32_t next = 500; int led = 0;\n    for (;;) {\n        if (ms >= next) {\n            next += 500; led = !led;\n            if (led) LPC_GPIO2->FIOSET = 1u << 0; else LPC_GPIO2->FIOCLR = 1u << 0;\n            puts_(\"t = \"); putu(ms); puts_(\" ms\\r\\n\");\n        }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"led1","type":"led","x":140,"y":380,"attrs":{"color":"red"}}],"wires":[["led1:A","lpc1768:P2.0","green"],["led1:C","lpc1768:GND.3","black"]]},"board":"lpc1768"},{"id":"lpc_knight","title":"LPC1768 LED bar: Knight Rider on P2.0-P2.9","src":"#include <stdint.h>\n#include \"lpc17xx.h\"\n\n/* LED bar graph on P2.0 to P2.9: a lit LED sweeps back and forth. CCLK = 4 MHz, SysTick gives the 1 ms time base. */\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\n\nint main(void) {\n    LPC_GPIO2->FIODIR |= 0x3FF;                         /* P2.0 - P2.9 outputs */\n    SysTick->LOAD = 4000 - 1; SysTick->CTRL = 7;\n    int pos = 0, dir = 1; uint32_t next = 80;\n    for (;;) {\n        if (ms >= next) {\n            next += 80;\n            LPC_GPIO2->FIOCLR = 0x3FF;\n            LPC_GPIO2->FIOSET = 1u << pos;\n            if (pos == 9) dir = -1; else if (pos == 0) dir = 1;\n            pos += dir;\n        }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"bar1","type":"bar","x":60,"y":395,"attrs":{"color":"green"}}],"wires":[["bar1:A1","lpc1768:P2.0","green"],["bar1:C1","lpc1768:GND.3","black"],["bar1:A2","lpc1768:P2.1","green"],["bar1:C2","lpc1768:GND.3","black"],["bar1:A3","lpc1768:P2.2","green"],["bar1:C3","lpc1768:GND.3","black"],["bar1:A4","lpc1768:P2.3","green"],["bar1:C4","lpc1768:GND.3","black"],["bar1:A5","lpc1768:P2.4","green"],["bar1:C5","lpc1768:GND.3","black"],["bar1:A6","lpc1768:P2.5","green"],["bar1:C6","lpc1768:GND.3","black"],["bar1:A7","lpc1768:P2.6","green"],["bar1:C7","lpc1768:GND.3","black"],["bar1:A8","lpc1768:P2.7","green"],["bar1:C8","lpc1768:GND.3","black"],["bar1:A9","lpc1768:P2.8","green"],["bar1:C9","lpc1768:GND.3","black"],["bar1:A10","lpc1768:P2.9","green"],["bar1:C10","lpc1768:GND.3","black"]]},"board":"lpc1768"},{"id":"lpc_adc","title":"LPC1768 ADC: potentiometer on P1.31 (AD0.5) + UART0","src":"#include <stdint.h>\n#include \"lpc17xx.h\"\n\n/* Potentiometer on P1.31 = AD0.5. The reading is printed on UART0 twice a second; the LED on P2.0 lights above half scale.\n   CCLK = 4 MHz, PCLK = 1 MHz, ADC clock = PCLK / 4 = 250 kHz, one conversion = 65 ADC clocks = 260 us. */\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\n\nstatic void putc_(char c) { while (!(LPC_UART0->LSR & LSR_THRE)); LPC_UART0->THR = c; }\nstatic void puts_(const char *s) { while (*s) putc_(*s++); }\nstatic void putu(uint32_t v) { char b[11]; int n = 0; do { b[n++] = '0' + v % 10; v /= 10; } while (v); while (n) putc_(b[--n]); }\n\nstatic void adc_init(void) {\n    LPC_SC->PCONP |= PCONP_PCADC;                                    /* power the ADC block */\n    LPC_PINCON->PINSEL3 |= 3u << 30;                                 /* P1.31 = AD0.5 */\n    LPC_PINCON->PINMODE3 = (LPC_PINCON->PINMODE3 & ~(3u << 30)) | (2u << 30);   /* neither pull-up nor pull-down */\n    LPC_ADC->ADCR = (1u << 5) | (3u << 8) | ADCR_PDN;                /* channel 5, CLKDIV = 3, operational */\n}\nstatic uint32_t adc_read(void) {\n    LPC_ADC->ADCR |= ADCR_START_NOW;\n    uint32_t v;\n    do { v = LPC_ADC->ADGDR; } while (!(v & ADGDR_DONE));            /* reading ADGDR clears DONE */\n    LPC_ADC->ADCR &= ~(7u << 24);\n    return (v >> 4) & 0xFFF;\n}\n\nint main(void) {\n    LPC_PINCON->PINSEL0 |= (1u << 4) | (1u << 6);\n    LPC_UART0->LCR = LCR_DLAB | 3; LPC_UART0->DLL = 6; LPC_UART0->DLM = 0; LPC_UART0->FDR = (12u << 4) | 1; LPC_UART0->LCR = 3; LPC_UART0->FCR = 7;\n    LPC_GPIO2->FIODIR |= 1u << 0;\n    SysTick->LOAD = 4000 - 1; SysTick->CTRL = 7;\n    adc_init();\n    puts_(\"ADC on P1.31 (AD0.5), 12 bit\\r\\n\");\n    uint32_t next = 500;\n    for (;;) {\n        if (ms >= next) {\n            next += 500;\n            uint32_t v = adc_read();\n            if (v > 2048) LPC_GPIO2->FIOSET = 1u << 0; else LPC_GPIO2->FIOCLR = 1u << 0;\n            puts_(\"AD0.5 = \"); putu(v); puts_(\"  (\"); putu(v * 3300 / 4095); puts_(\" mV)\\r\\n\");\n        }\n    }\n}\n","b64":"","circuit":{"parts":[{"id":"led1","type":"led","x":140,"y":380,"attrs":{"color":"red"}},{"id":"pot1","type":"pot","x":320,"y":390,"attrs":{}}],"wires":[["led1:A","lpc1768:P2.0","green"],["led1:C","lpc1768:GND.3","black"],["pot1:SIG","lpc1768:P1.31","orange"],["pot1:VCC","lpc1768:3V3.3","red"],["pot1:GND","lpc1768:GND.3","black"]]},"board":"lpc1768"},{"id":"lpc_i2c_eeprom","title":"LPC1768 I2C2: AT24C32 EEPROM boot counter (status-code driver)","src":"#include <stdint.h>\n#include \"lpc17xx.h\"\n\n/* Non-volatile boot counter in an AT24C32 EEPROM module (I2C address 0x50, 2-byte memory addresses, 32-byte pages) on I2C2:\n   SDA2 = P0.10, SCL2 = P0.11. Press Stop and Run again: the counter keeps counting because the EEPROM keeps its contents.\n   The bare module has NO pull-up resistors, so the two 4.7k resistors in the circuit are required. A write takes about 5 ms\n   during which the chip does not acknowledge its address (status 0x20): that is how ACK polling finds out the write is done.\n   The driver follows the status codes of the LPC17xx I2C block and every wait has a timeout, so a wiring mistake is reported. */\nstatic volatile uint32_t ms;\nvoid SysTick_Handler(void) { ms++; }\n\nstatic void putc_(char c) { while (!(LPC_UART0->LSR & LSR_THRE)); LPC_UART0->THR = c; }\nstatic void puts_(const char *s) { while (*s) putc_(*s++); }\nstatic void putu(uint32_t v) { char b[11]; int n = 0; do { b[n++] = '0' + v % 10; v /= 10; } while (v); while (n) putc_(b[--n]); }\n\n#define I2C LPC_I2C2\n#define TIMEOUT 30000\nstatic uint32_t wait_si(void) { for (int n = TIMEOUT; n; n--) if (I2C->I2CONSET & I2C_SI) return I2C->I2STAT; return 0xFFFF; }\nstatic uint32_t go(uint32_t clr) { I2C->I2CONCLR = clr; return wait_si(); }\nstatic void stop(void) { I2C->I2CONSET = I2C_STO; I2C->I2CONCLR = I2C_SI; for (int n = TIMEOUT; n && (I2C->I2CONSET & I2C_STO); n--); }\nstatic int fail(uint32_t s) { if (s == 0xFFFF) { I2C->I2CONCLR = I2C_I2EN; I2C->I2CONSET = I2C_I2EN; return 2; } stop(); return 1; }   /* 1 = NACK / unexpected status, 2 = bus fault */\n\nstatic void i2c_init(void) {\n    LPC_SC->PCONP |= PCONP_PCI2C2;\n    LPC_PINCON->PINSEL0 = (LPC_PINCON->PINSEL0 & ~((3u << 20) | (3u << 22))) | (2u << 20) | (2u << 22);       /* P0.10 SDA2, P0.11 SCL2 */\n    LPC_PINCON->PINMODE0 = (LPC_PINCON->PINMODE0 & ~((3u << 20) | (3u << 22))) | (2u << 20) | (2u << 22);     /* no internal pull: external 4.7k */\n    I2C->I2SCLH = 5; I2C->I2SCLL = 5;                      /* PCLK = 1 MHz: 100 kHz */\n    I2C->I2CONCLR = I2C_AA | I2C_SI | I2C_STA | I2C_I2EN;\n    I2C->I2CONSET = I2C_I2EN;\n}\nstatic int addr_phase(uint8_t sla, uint32_t ok) {           /* START (or repeated START already requested) + address byte */\n    uint32_t s = wait_si();\n    if (s != 0x08 && s != 0x10) return fail(s);\n    I2C->I2DAT = sla; s = go(I2C_STA | I2C_SI);\n    return s == ok ? 0 : fail(s);\n}\nstatic int ee_write(uint16_t a, const uint8_t *d, int n) {\n    I2C->I2CONSET = I2C_STA;\n    int r = addr_phase(0xA0, 0x18); if (r) return r;\n    I2C->I2DAT = a >> 8;   uint32_t s = go(I2C_SI); if (s != 0x28) return fail(s);\n    I2C->I2DAT = a & 255;  s = go(I2C_SI);          if (s != 0x28) return fail(s);\n    for (int i = 0; i < n; i++) { I2C->I2DAT = d[i]; s = go(I2C_SI); if (s != 0x28) return fail(s); }\n    stop(); return 0;\n}\nstatic int ee_ready(void) {                                 /* ACK polling: 1 = still writing, 0 = ready */\n    I2C->I2CONSET = I2C_STA;\n    int r = addr_phase(0xA0, 0x18); if (r == 0) stop(); return r;\n}\nstatic int ee_read(uint16_t a, uint8_t *d, int n) {\n    I2C->I2CONSET = I2C_STA;\n    int r = addr_phase(0xA0, 0x18); if (r) return r;\n    I2C->I2DAT = a >> 8;   uint32_t s = go(I2C_SI); if (s != 0x28) return fail(s);\n    I2C->I2DAT = a & 255;  s = go(I2C_SI);          if (s != 0x28) return fail(s);\n    I2C->I2CONSET = I2C_STA; s = go(I2C_SI);                /* repeated START */\n    r = addr_phase(0xA1, 0x40); if (r) return r;\n    for (int i = 0; i < n; i++) {\n        if (i < n - 1) I2C->I2CONSET = I2C_AA; else I2C->I2CONCLR = I2C_AA;   /* ACK every byte but the last */\n        s = go(I2C_SI);\n        if (s != (i < n - 1 ? 0x50 : 0x58)) return fail(s);\n        d[i] = (uint8_t)I2C->I2DAT;\n    }\n    stop(); return 0;\n}\n\nint main(void) {\n    LPC_PINCON->PINSEL0 |= (1u << 4) | (1u << 6);\n    LPC_UART0->LCR = LCR_DLAB | 3; LPC_UART0->DLL = 6; LPC_UART0->DLM = 0; LPC_UART0->FDR = (12u << 4) | 1; LPC_UART0->LCR = 3; LPC_UART0->FCR = 7;\n    SysTick->LOAD = 4000 - 1; SysTick->CTRL = 7;\n    i2c_init();\n    puts_(\"AT24C32 on I2C2 (SDA2 P0.10, SCL2 P0.11)\\r\\n\");\n    uint8_t rec[5];\n    int r = ee_read(0, rec, 5);\n    if (r) { puts_(r == 1 ? \"EEPROM does not answer at 0x50: check wiring and address\\r\\n\" : \"I2C bus fault: SCL or SDA cannot rise, are the 4.7k pull-ups fitted?\\r\\n\"); for (;;); }\n    uint32_t count = (rec[0] == 0xA5) ? ((uint32_t)rec[1] | rec[2] << 8 | rec[3] << 16 | (uint32_t)rec[4] << 24) : 0;\n    count++;\n    rec[0] = 0xA5; rec[1] = count; rec[2] = count >> 8; rec[3] = count >> 16; rec[4] = count >> 24;\n    r = ee_write(0, rec, 5);\n    if (r) { puts_(\"write failed\\r\\n\"); for (;;); }\n    uint32_t t0 = ms; int polls = 0;\n    while (ee_ready() && ms - t0 < 50) polls++;\n    uint32_t dt = ms - t0;                                  /* measure before printing: the UART is slow */\n    puts_(\"EEPROM boot counter = \"); putu(count); puts_(\"  (write cycle took \"); putu(dt); puts_(\" ms, \"); putu(polls); puts_(\" ACK polls)\\r\\n\");\n    for (;;);\n}\n","b64":"","circuit":{"parts":[{"id":"ee1","type":"at24","x":520,"y":130,"attrs":{"size":"24C32","wp":"0"}},{"id":"r1","type":"res","x":660,"y":80,"attrs":{"value":"4700"}},{"id":"r2","type":"res","x":660,"y":120,"attrs":{"value":"4700"}}],"wires":[["ee1:GND","lpc1768:GND.1","black"],["ee1:VCC","lpc1768:3V3.1","red"],["ee1:SCL","lpc1768:P0.11","green"],["ee1:SDA","lpc1768:P0.10","blue"],["r1:1","lpc1768:P0.11","green"],["r1:2","lpc1768:3V3.1","red"],["r2:1","lpc1768:P0.10","blue"],["r2:2","lpc1768:3V3.1","red"]]},"board":"lpc1768"}];
